(window.SCI_DATA = window.SCI_DATA || []).push({"id": "phy-4", "subject": "理化", "chapter": "第四章", "title": "光、影像與顏色", "total": 157, "levels": {"必考": 20, "常考": 10}, "secs": {"4-1": "光的傳播", "4-2": "光的反射與面鏡", "4-3": "光的折射", "4-4": "透鏡與成像", "4-5": "色散與顏色"}, "mapname": {}, "concepts": [{"id": "k8", "name": "光的折射與偏折規律", "n": 23, "level": "必考", "sec": "4-3", "card": {"說明": "光由一種介質斜射進入另一種傳播速率不同的介質時，在兩介質交界面處因傳播速率改變，導致前進方向發生偏折的現象稱為折射。若垂直界面入射（入射角 = 0^°），雖然速率改變，但行進方向不偏折（折射角亦為 0^°）。", "關鍵名詞": "<div class=\"kv\"><b>折射線與折射角（angle r）</b>：折射光線與<b>法線</b>之間的夾角稱為折射角。</div><div class=\"kv\"><b>折射規律（快慢偏向口訣）</b>：</div><div class=\"kv\"><b>由快介質進入慢介質</b>（如空氣 → 水、空氣 → 玻璃）：折射光線<b>偏向法線</b>，<b>折射角小於入射角</b>（angle r < angle i）。</div><div class=\"kv\"><b>由慢介質進入快介質</b>（如水 → 空氣、玻璃 → 空氣）：折射光線<b>偏離法線</b>，<b>折射角大於入射角</b>（angle r > angle i）。</div><div class=\"kv\">入射角與法線夾角愈大，折射角也隨之增大；但<b>光速快的一方夾角恆大，光速慢的一方夾角恆小</b>。</div>", "因果／影響": "光在各介質中的偏折程度與該介質的光速差成正比，速差愈大，偏折角度愈劇烈。", "出處": "自修第 178–180 頁／講義第 137–139 頁。", "標示": "自修與講義皆標記為<b>【重點／必考】</b>，會考必出作圖題。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 12, "ids": ["s4-15", "s4-19", "s4-40", "s4-103", "s4-104", "s4-105", "s4-106", "s4-107", "s4-111", "s4-121", "s4-141", "s4-156"]}, {"t": "計算題", "n": 3, "ids": ["s4-18", "s4-113", "s4-114"]}, {"t": "觀念判斷", "n": 8, "ids": ["s4-14", "s4-91", "s4-92", "s4-93", "s4-94", "s4-109", "s4-110", "s4-115"]}]}, {"id": "k11", "name": "凸透鏡與凹透鏡的成像規律", "n": 20, "level": "必考", "sec": "4-4", "card": {"說明": "凸透鏡成像隨物體置於主軸上的物距位置不同，可形成倒立實像（縮小、等大、放大）或正立放大虛像，以 2f 處為大小分界點、以 f 處為虛實分界點；凹透鏡則無論物體放在鏡前任何位置，折射光線一律發散，永遠只能形成「<b>正立、縮小的虛像</b>」，成像位置恆在同側一倍焦距內。", "關鍵名詞": "<div class=\"kv\"><b>凸透鏡成像六大位置規律</b>：</div><div class=\"kv\"><b>物在無窮遠處</b>：像在鏡後<b>焦點（F）</b>上，成極小的「<b>一點實像</b>」。</div><div class=\"kv\"><b>物在兩倍焦距外（p > 2f）</b>：像在鏡後一倍焦距至兩倍焦距間（f < q < 2f），成「<b>倒立、縮小實像</b>」（照相機原理）。</div><div class=\"kv\"><b>物在兩倍焦距上（p = 2f）</b>：像恰在鏡後兩倍焦距上（q = 2f），成「<b>倒立、等大實像</b>」（影印機原理）。</div><div class=\"kv\"><b>物在焦距與兩倍焦距間（f < p < 2f）</b>：像在鏡後兩倍焦距外（q > 2f），成「<b>倒立、放大實像</b>」（投影機、電影放映機原理）。</div><div class=\"kv\"><b>物在焦點上（p = f）</b>：折射光線互相平行，在無窮遠處交會，「<b>不成像</b>」（探照燈原理）。</div><div class=\"kv\"><b>物在焦距內（p < f）</b>：折射光發散，反向延長線交會於物體同側鏡前，成「<b>正立、放大虛像</b>」（放大鏡原理）。</div><div class=\"kv\"><b>遮蔽效應</b>：若將凸透鏡遮住一半（如用黑紙遮蔽上半部），成像性質、大小與位置完全不變，但因折射光線總量減半，<b>影像亮度變暗</b>。</div>", "因果／影響": "<div class=\"kv\">物體從兩倍焦距外逐漸向凸透鏡焦點靠近時，鏡後的實像會由焦點逐漸向外遠離透鏡，且<b>像的體積愈變愈大</b>；</div><div class=\"kv\">一旦跨入焦點內，則物體愈靠近透鏡，所成的放大虛像愈變愈小。</div>", "出處": "自修第 193–195 頁／講義第 146–149 頁。", "標示": "自修與講義皆列為全冊理化難度最高、會考比重最大的<b>【必考／易錯】</b>精熟核心。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 11, "ids": ["s4-22", "s4-26", "s4-29", "s4-33", "s4-39", "s4-61", "s4-124", "s4-125", "s4-147", "s4-151", "s4-153"]}, {"t": "觀念判斷", "n": 9, "ids": ["s4-21", "s4-25", "s4-123", "s4-126", "s4-127", "s4-134", "s4-143", "s4-152", "s4-157"]}]}, {"id": "k6", "name": "平面鏡成像", "n": 18, "level": "常考", "sec": "4-2", "card": {"說明": "物體在平面鏡前發出的光線經鏡面反射後進入人眼，大腦會依光線直線行進的習慣，將反射光線沿反方向向鏡後延伸，交會形成發光點的虛像。平面鏡成像具有完全對稱的幾何特性。", "關鍵名詞": "<div class=\"kv\"><b>平面鏡成像性質</b>：成「<b>正立、等大、左右相反的虛像</b>」。</div><div class=\"kv\"><b>物距等於像距</b>：物體到鏡面的垂直距離等於像到鏡面的垂直距離（p = q）。</div><div class=\"kv\"><b>對稱軸特性</b>：物體與像的連線必與鏡面垂直，且被鏡面垂直平分，物與像以鏡面為對稱軸呈鏡面對稱。</div><div class=\"kv\"><b>虛像</b>：由反射光線的「反向延長線」交會所形成的像，並非真實光線匯聚，因此<b>無法呈現在紙屏上</b>，只能用肉眼透過鏡面觀察。</div>", "因果／影響": "<div class=\"kv\">救護車車頭刻意印上左右反轉的「車體字」（ECNALUBMA），讓前方駕駛透過後視鏡（平面鏡）能看到正向的「AMBULANCE」字樣；</div><div class=\"kv\">站在鏡前無論後退或前進，人鏡距離改變，但<b>鏡中像的大小永遠等於物體實際大小</b>，感覺變小僅是視角縮小的視覺暫留效果。</div><div class=\"kv\"><b>全身鏡最小鏡長</b>：人在立正姿勢下欲看到自己完整的全身像，平面鏡的最小長度只需<b>身高的一半（1/2 H）</b>，且鏡底離地高度必須為眼睛離地高度的一半（1/2 h），與人站立離鏡子的遠近完全無關。</div>", "出處": "自修第 160–162 頁／講義第 129–131 頁。", "標示": "自修與講義皆列為整章第一級<b>【必考／易錯】</b>觀念。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 10, "ids": ["s4-10", "s4-11", "s4-37", "s4-49", "s4-88", "s4-89", "s4-90", "s4-119", "s4-132", "s4-154"]}, {"t": "計算題", "n": 2, "ids": ["s4-12", "s4-118"]}, {"t": "觀念判斷", "n": 6, "ids": ["s4-34", "s4-48", "s4-83", "s4-84", "s4-86", "s4-129"]}]}, {"id": "k3", "name": "針孔成像", "n": 16, "level": "常考", "sec": "4-1", "card": {"說明": "光源各點發出的光線朝四面八方直線前進，只有少數光線能穿過細小的針孔，光線在針孔處交錯傳遞至後方紙屏上，形成與原物體「<b>上下顛倒、左右相反</b>」的像。此成像由真實光線交會而成，屬於<b>實像</b>，可於紙屏上直接顯現。", "關鍵名詞": "<div class=\"kv\"><b>針孔成像</b>：光經由極微小孔洞因直線傳播交錯，在後方屏幕上呈現倒立實像的現象。</div><div class=\"kv\"><b>實像</b>：由物體發出的光線實際相交匯聚而成的像，能投射在紙屏（屏幕）上，亦可由眼睛直接看到。</div><div class=\"kv\"><b>物距（p）與像距（q）</b>：物體到針孔的距離為物距，針孔到紙屏的距離為像距。</div>", "因果／影響": "<div class=\"kv\"><b>像的大小比例</b>：由相似三角形幾何關係可知：fractext{像長}}{text物長 =frac{text像距 qtext{物距 } p}（若像距大於物距則放大，像距小於物距則縮小）。</div><div class=\"kv\"><b>針孔大小與個數</b>：針孔愈小，成像形狀愈清晰但亮度較暗；針孔變大時，相當於多個針孔的像交錯重疊，亮度變亮但像變得模糊；若多戳幾個小孔，紙屏上會出現多個相同的倒立像。</div><div class=\"kv\"><b>生活實例</b>：夏日陽光透過樹葉縫隙在地面形成的無數個圓形光斑，即為太陽的「針孔成像」（圓形是太陽的像，非樹葉縫隙的形狀）。</div>", "出處": "自修第 148–149 頁／講義第 119–120 頁。", "標示": "自修與講義皆標示為歷屆會考實驗題最高頻率<b>【必考／易錯】</b>。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 9, "ids": ["s4-5", "s4-44", "s4-58", "s4-67", "s4-74", "s4-80", "s4-81", "s4-82", "s4-140"]}, {"t": "觀念判斷", "n": 7, "ids": ["s4-3", "s4-57", "s4-66", "s4-72", "s4-73", "s4-77", "s4-78"]}]}, {"id": "k9", "name": "生活中的光折射現象", "n": 16, "level": "常考", "sec": "4-3", "card": {"說明": "當我們觀看水中的物體時，來自水下物體的光線從水中（慢介質）斜射入空氣（快介質）時會偏離法線折射入人眼，眼睛沿逆向直線延長線看去，會覺得物體位置抬升，導致視覺深度小於實際深度。", "關鍵名詞": "<div class=\"kv\"><b>視深變淺</b>：從岸上觀看清澈的水池、溪流時，水底反射的光線折射使水底看起來比實際深度更淺的現象。</div><div class=\"kv\"><b>海市蜃樓</b>：地表空氣受日照不均勻加熱，各層空氣密度與溫度不同導致光速不同，光線連續折射形成的虛幻影像。</div>", "因果／影響": "<div class=\"kv\">筷子斜插在水杯中，在水面交界處看起來向上彎折或折斷；</div><div class=\"kv\">站在泳池旁看池底或池中人的腿看起來變短；</div><div class=\"kv\">叉魚時，因看見的是浮上來的虛像，必須朝著眼睛所看見<b>魚的影像下方</b>投擲才能扎中真魚。</div>", "出處": "自修第 180–181 頁／講義第 138 頁。", "標示": "自修標為<b>【重點2】</b>，生活素養題<b>【必考／易錯】</b>。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 7, "ids": ["s4-20", "s4-38", "s4-100", "s4-102", "s4-108", "s4-112", "s4-148"]}, {"t": "觀念判斷", "n": 9, "ids": ["s4-4", "s4-17", "s4-42", "s4-64", "s4-97", "s4-98", "s4-99", "s4-101", "s4-133"]}]}, {"id": "k14", "name": "光的三原色與物體的顏色成因", "n": 16, "level": "常考", "sec": "4-5", "card": {"說明": "人眼視網膜對紅、綠、藍三種色光最為敏感，自然界中幾乎所有的色光均可由這三種基本色光以不同比例重疊混合出來。物體在光線照射下呈現的顏色，完全取決於物體對入射光線的<b>選擇性吸收、反射（不透明體）或透射（透明體）</b>。", "關鍵名詞": "<div class=\"kv\"><b>光的三原色（RGB）</b>：<b>紅光（R）、綠光（G）、藍光（B）</b>。</div><div class=\"kv\">紅光 + 綠光 = <b>黃光</b>；</div><div class=\"kv\">綠光 + 藍光 = <b>青光（藍綠光）</b>；</div><div class=\"kv\">紅光 + 藍光 = <b>洋紅色光（紫紅光）</b>；</div><div class=\"kv\">紅光 + 綠光 + 藍光 = <b>白光</b>。</div><div class=\"kv\"><b>透明體的顏色</b>：由其<b>透過的色光</b>決定。無色透明體可透過所有色光；有色透明體只允許與自身顏色相同的色光通過，並吸收其餘色光（如紅色玻璃紙只透過紅光，其餘色光全被吸收）。</div><div class=\"kv\"><b>不透明體的顏色</b>：由其<b>反射的色光</b>決定。白色物體反射所有色光；黑色物體吸收所有色光；有色物體只反射與自身顏色相同的色光，並吸收其他色光（如紅蘋果在白光照射下反射紅光呈紅色，但在綠光照射下因吸收綠光而呈現黑色）。</div>", "因果／影響": "<div class=\"kv\">電視、電腦與手機螢幕的液晶像素，均是由紅、綠、藍三種微小發光單元混合出全彩畫面；</div><div class=\"kv\">舞台燈光若打純藍光，穿著白衣紅裙的舞者看起來會變成「藍衣黑裙」（白衣反射藍光呈藍色，紅裙吸收藍光無光反射呈黑色）。</div>", "出處": "自修第 214–216 頁／講義第 156–159 頁。", "標示": "自修與講義皆列為基測會考最經典<b>【易錯／必考】</b>題型。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 7, "ids": ["s4-24", "s4-31", "s4-55", "s4-56", "s4-138", "s4-142", "s4-144"]}, {"t": "計算題", "n": 1, "ids": ["s4-137"]}, {"t": "觀念判斷", "n": 8, "ids": ["s4-27", "s4-28", "s4-32", "s4-54", "s4-62", "s4-135", "s4-136", "s4-146"]}]}, {"id": "k5", "name": "光的反射與反射定律", "n": 10, "level": "常考", "sec": "4-2", "card": {"說明": "光在傳播途中遇到不同物質的交界面時，光線折回原介質中繼續傳播的現象稱為反射。無論反射面是平滑的光滑面（鏡面反射）或是粗糙不平的表面（漫反射），<b>每一條光線皆絕對遵守反射定律</b>。", "關鍵名詞": "<div class=\"kv\"><b>法線</b>：通過入射點且與反射面相互<b>垂直</b>的虛擬假想線。</div><div class=\"kv\"><b>入射角（angle i）</b>：入射光線與<b>法線</b>的夾角。</div><div class=\"kv\"><b>反射角（angle r）</b>：反射光線與<b>法線</b>的夾角。</div><div class=\"kv\"><b>反射定律</b>：</div><div class=\"kv\">入射光線、反射光線與法線都在同一平面上，且入射線與反射線分居法線的兩側。</div><div class=\"kv\"><b>入射角必等於反射角</b>（angle i = angle r）。</div><div class=\"kv\"><b>光的可逆性</b>：若光線逆著原本反射光線的方向入射，則反射光必沿原本入射光線的路徑射出。</div>", "因果／影響": "粗糙黑板或白紙發生漫反射，使各方向的人都能看見上面的文字；光滑鏡面則因單向反射，特定角度會感到刺眼反光。", "出處": "自修第 159–160 頁／講義第 126–128 頁。", "標示": "自修標為<b>【重點1】</b>，講義列為幾何角度計算必備<b>【必考】</b>。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 4, "ids": ["s4-6", "s4-46", "s4-47", "s4-116"]}, {"t": "計算題", "n": 3, "ids": ["s4-87", "s4-120", "s4-150"]}, {"t": "觀念判斷", "n": 3, "ids": ["s4-1", "s4-7", "s4-85"]}]}, {"id": "k2", "name": "影子的形成與日晷", "n": 9, "level": "一般", "sec": "4-1", "card": {"說明": "光在直線傳播途中若遇到不透明的障礙物，光線無法穿透，便會在障礙物的後方背光區域形成陰影，即為影子。古代計時工具「日晷」即是利用太陽照射晷針所產生的影子方位與長短變化來測定時刻。", "關鍵名詞": "<div class=\"kv\"><b>影子</b>：不透明物體阻擋直線前進的光線，在其後方形成的黑暗遮蔽區域。</div><div class=\"kv\"><b>日晷</b>：利用太陽方位隨時間變動使晷針影子的長度與方位改變，藉以測量時間的古代計時工具。</div>", "因果／影響": "<div class=\"kv\">太陽光視為平行光，相同高度的物體無論身在何處，影長皆相同；</div><div class=\"kv\">點光源（如路燈、蠟燭）下，物體離光源愈近（或離屏幕愈遠），影子面積愈大。</div>", "出處": "自修第 148–149 頁／講義第 118、120 頁。", "標示": "講義「老師的話」列為相似三角形幾何計算的<b>【必考／重點】</b>題型。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 3, "ids": ["s4-2", "s4-43", "s4-71"]}, {"t": "計算題", "n": 2, "ids": ["s4-68", "s4-75"]}, {"t": "觀念判斷", "n": 4, "ids": ["s4-8", "s4-70", "s4-79", "s4-131"]}]}, {"id": "k7", "name": "面鏡的種類與應用（凸面鏡與凹面鏡）", "n": 9, "level": "一般", "sec": "4-2", "card": {"說明": "反射面為曲面的面鏡稱為曲面鏡，主要依反射面的凸出或凹陷分為凸面鏡與凹面鏡，兩者反射均嚴格遵循反射定律，但會改變光線的匯聚與發散方向。", "關鍵名詞": "<div class=\"kv\"><b>凸面鏡</b>：反射面外凸的曲面鏡。平行入射光反射後向外<b>發散</b>，反射光反向延長線交於鏡後的虛焦點；其成像恆為「<b>正立、縮小的虛像</b>」，具有縮小影像而<b>擴大視野（視角廣）</b>的特性。</div><div class=\"kv\"><b>凹面鏡</b>：反射面內凹的曲面鏡。平行入射光反射後向內<b>會聚</b>於鏡前的實焦點；物體置於焦點內時，成「<b>正立、放大的虛像</b>」；若將光源放在凹面鏡的焦點上，反射後會射出<b>平行光束</b>。</div>", "因果／影響": "<div class=\"kv\"><b>凸面鏡應用</b>：道路轉彎處的反光鏡、汽車與機車的後視鏡、超商防竊角落後照鏡；</div><div class=\"kv\"><b>凹面鏡應用</b>：手電筒與汽車車頭燈的反光罩（燈絲置於焦點）、太陽爐（聚光加熱）、耳鼻喉科醫師的額鏡、化妝放大修容鏡。</div>", "出處": "自修第 163–164 頁／講義第 132 頁。", "標示": "自修與講義皆列為生活情境素養題<b>【重點／必考】</b>。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 2, "ids": ["s4-13", "s4-155"]}, {"t": "觀念判斷", "n": 7, "ids": ["s4-9", "s4-16", "s4-50", "s4-51", "s4-60", "s4-128", "s4-130"]}]}, {"id": "k12", "name": "生活中的透鏡與光學儀器（照相機、眼睛與視力矯正）", "n": 5, "level": "一般", "sec": "4-4", "card": {"說明": "許多光學儀器皆利用透鏡折射原理製成。照相機利用凸透鏡將遠處景物縮小成像於感光元件上；人眼的眼球構造與照相機極為類似，水晶體相當於可調焦距的凸透鏡，視網膜相當於感光元件或底片。", "關鍵名詞": "<div class=\"kv\"><b>照相機構造與成像</b>：鏡頭為凸透鏡組，光圈控制進光量，快門控制曝光時間，底片／感光元件在鏡後 f ～ 2f 間，成「<b>倒立、縮小實像</b>」。</div><div class=\"kv\"><b>正常人眼調節機制</b>：看遠處物體時，睫狀肌放鬆，水晶體扁平變薄（焦距變長）；看近處物體時，睫狀肌緊縮，水晶體凸起變厚（焦距變短），使影像準確聚焦於視網膜上。</div><div class=\"kv\"><b>近視眼與矯正</b>：眼球前後徑過長或水晶體折光力太強（焦距過短），使遠處景物的影像落在<b>視網膜前方</b>；需配戴「<b>凹透鏡</b>」發散光線，使成像向後移至視網膜上。</div><div class=\"kv\"><b>遠視眼與矯正</b>：眼球前後徑過短或水晶體折光力太弱（焦距過長），使近處景物的影像落在<b>視網膜後方</b>；需配戴「<b>凸透鏡</b>」匯聚光線，使成像向前移至視網膜上。</div><div class=\"kv\"><b>複式顯微鏡</b>：由兩組凸透鏡組成，物鏡（焦距短）將微小標本放大為倒立放大實像，落在目鏡（焦距長）的一倍焦距內；目鏡再將該實像放大為正立放大虛像，因此最終人眼觀察到的是「<b>倒立、放大的虛像</b>」。</div>", "因果／影響": "近視眼戴凹透鏡、老花眼與遠視眼戴凸透鏡；拿近視眼鏡看書本字體會縮小，拿老花眼鏡看書本字體可放大。", "出處": "自修第 196–198 頁／講義第 150–152 頁。", "標示": "講義主題 3 標示為健康生活應用<b>【重點／必考】</b>。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 2, "ids": ["s4-23", "s4-149"]}, {"t": "觀念判斷", "n": 3, "ids": ["s4-59", "s4-63", "s4-139"]}]}, {"id": "k1", "name": "光的直進性與看見物體的條件", "n": 4, "level": "一般", "sec": "4-1", "card": {"說明": "光在真空或均勻介質中是以直線傳播的，不會發生偏折或彎曲，稱為光的直進性。人眼之所以能看見物體，必須有光線進入眼睛：發光體本身發出的光直接射入眼睛，或不發光物體反射外來光線進入眼睛，再經大腦解讀後形成視覺。", "關鍵名詞": "<div class=\"kv\"><b>發光體（光源）</b>：能自行發光的物體，如太陽、通電的燈泡、點燃的蠟燭。</div><div class=\"kv\"><b>光的直進性</b>：光在同種均勻介質中沿直線前進的傳播特性。</div>", "因果／影響": "因為光沿直線前進，排隊對齊（單眼瞄準）、張開嘴巴卻看不見食道或胃、皮影戲、木工取直線等現象皆由此原理而來。", "出處": "自修第 148 頁／講義第 118 頁。", "標示": "自修標為<b>【重點1、2】</b>，講義標為主題 1 之核心<b>【重點】</b>。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 2, "ids": ["s4-41", "s4-117"]}, {"t": "觀念判斷", "n": 2, "ids": ["s4-65", "s4-69"]}]}, {"id": "k4", "name": "光的傳播速率與光年", "n": 4, "level": "一般", "sec": "4-1", "card": {"說明": "光是屬於<b>非力學波（電磁波）</b>，傳播時不需要任何介質，在<b>真空中傳播速度最快</b>，約為每秒 3 × 10⁸ 公尺（3 × 10⁵ 公里／秒，常用 c 表示）。光在不同透明介質中傳播時速率會減慢，介質緊密密度或光學阻礙愈大，光速愈慢。", "關鍵名詞": "<div class=\"kv\"><b>光速（c）</b>：光在真空中前進的速度（c approx 3 × 10⁸ m/s）。光在常見介質中的傳播速率順序為：<b>真空（c） approx 空氣 > 水（約 3/4c） > 玻璃（約 2/3c） > 鑽石（約 5/12c）</b>。</div><div class=\"kv\"><b>光年</b>：光在真空中行走一整年所經過的「<b>距離</b>」（長度單位，非時間單位），約為 9.46 × 10¹² 公里。</div>", "因果／影響": "打雷與閃電同時發生，但因光速遠大於聲速（空氣聲速約 340 m/s），遠處觀察者必定先看見閃電亮光，數秒後才聽到雷聲。", "出處": "自修第 149 頁／講義第 118、137 頁。", "標示": "自修列為<b>【重點3】</b>，講義列為計算測距常見<b>【重點】</b>。"}, "imgs": [], "clusters": [{"t": "計算題", "n": 1, "ids": ["s4-95"]}, {"t": "觀念判斷", "n": 3, "ids": ["s4-45", "s4-96", "s4-145"]}]}, {"id": "k13", "name": "光的色散與可見光譜", "n": 4, "level": "一般", "sec": "4-5", "card": {"說明": "白光並非單色光，而是由多種不同顏色的單色光混合而成的「複色光」。西元 1666 年英國科學家牛頓利用三稜鏡讓太陽光通過，發現不同顏色的光在玻璃中的傳播速率不同，導致折射偏折程度不同，太陽光因而展開成連續彩帶，此現象稱為光的色散。", "關鍵名詞": "<div class=\"kv\"><b>色散現象</b>：白光經三稜鏡折射後，依色光頻率與偏折角度不同而分散成紅、橙、黃、綠、藍、靛、紫等七彩連續光譜的現象。</div><div class=\"kv\"><b>可見光譜</b>：人眼視覺所能感受到的電磁波光帶，波長由長至短依序為「<b>紅、橙、黃、綠、藍、靛、紫</b>」。</div><div class=\"kv\"><b>折射率與偏折規律</b>：在玻璃三稜鏡中，<b>紅光波長最長、傳播速率最快、偏折角度最小（折射角最大）</b>；<b>紫光波長最短、傳播速率最慢、偏折角度最大（折射角最小）</b>。</div><div class=\"kv\"><b>單色光 vs. 複色光</b>：雷射光為單色光，通過三稜鏡只偏折不會色散；太陽光與日光燈白光為複色光，通過三稜鏡會發生色散。</div><div class=\"kv\"><b>彩虹成因</b>：雨後陽光射入空氣中懸浮的水滴，光線在水滴內經歷「<b>兩次折射、一次內部全反射</b>」後射出，形成外紅內紫的圓弧彩帶；觀賞彩虹必須<b>背對太陽</b>。</div>", "因果／影響": "", "出處": "自修第 213–214 頁／講義第 156–157 頁。", "標示": "自修與講義皆標為歷屆會考高頻率<b>【必考／重點】</b>。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 1, "ids": ["s4-36"]}, {"t": "觀念判斷", "n": 3, "ids": ["s4-52", "s4-53", "s4-76"]}]}, {"id": "k10", "name": "透鏡的種類與光學名詞", "n": 3, "level": "一般", "sec": "4-4", "card": {"說明": "透鏡是利用透明材質（如玻璃、塑膠）製成、利用<b>兩次折射原理</b>使光線前進方向產生匯聚或發散的光學元件。光經過透鏡時，折射光線永遠<b>朝向透鏡材質較厚的一端偏折</b>。", "關鍵名詞": "<div class=\"kv\"><b>凸透鏡（會聚透鏡）</b>：中央部位厚、邊緣較薄的透鏡（包含雙凸、平凸、凹凸透鏡）。平行於主軸的光線穿過凸透鏡折射後，會匯聚於鏡後一點，此點稱為<b>實焦點（F）</b>。</div><div class=\"kv\"><b>凹透鏡（發散透鏡）</b>：中央部位薄、邊緣較厚的透鏡（包含雙凹、平凹、凸凹透鏡）。平行於主軸的光線穿過凹透鏡折射後向外發散，折射光線的反向延長線交於鏡前一點，稱為<b>虛焦點（F）</b>。</div><div class=\"kv\"><b>鏡心（O）</b>：透鏡的幾何中心點，通過鏡心的光線傳播方向保持不變。</div><div class=\"kv\"><b>主軸</b>：通過鏡心且垂直於透鏡兩鏡面的對稱中心直線。</div><div class=\"kv\"><b>焦距（f）</b>：透鏡鏡心到焦點的直線距離。</div><div class=\"kv\"><b>兩倍焦距（2f）</b>：主軸上距離鏡心為兩倍焦距的基準點。</div>", "因果／影響": "拿凸透鏡正對太陽光照射，能在鏡後紙屏上聚焦成一個極小、極亮的高溫光點，此點到透鏡的垂直距離即為凸透鏡的焦距。", "出處": "自修第 191–192 頁／講義第 143–145 頁。", "標示": "講義主題 1 列為核心<b>【重點】</b>。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 2, "ids": ["s4-30", "s4-35"]}, {"t": "觀念判斷", "n": 1, "ids": ["s4-122"]}]}], "questions": [{"id": "s4-1", "no": "1", "c": "k5", "src": "翰林 C卷 第7回 第 1 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "有關「光的反射」的敘述，下列何者錯誤？", "o": ["光反射時，其入射角等於反射角", "光的反射是光在兩界面間反射回原介質的現象", "光反射時，入射線與反射線不一定要在同一平面上", "無論反射面是否為平面，光的反射都遵守反射定律"], "a": 2, "e": "反射定律有兩個重點：①入射角＝反射角；②入射線、反射線、法線三者在同一平面上。\n所以 (C)「不一定要在同一平面上」錯誤。\n不管是平面還是粗糙面（漫射），每一條光線都遵守反射定律。\n★ 反射定律：角度相等＋三線共平面。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-2", "no": "2", "c": "k2", "src": "翰林 C卷 第7回 第 2 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "如下圖所示，有一路燈，小強由圖中的丙點走向甲點（甲、乙相距 6 m，乙、丙相距 12 m），試問小強在地面上的影子長度大小順序為何？", "o": ["甲＝乙＝丙", "甲＞乙＞丙", "丙＞乙＞甲", "甲＞丙＞乙"], "a": 1, "e": "從路燈頂端畫一條線，經過小強頭頂延伸到地面，人腳到交點的距離就是影長。\n離路燈愈遠，光線愈斜，影子愈長。\n圖中甲離路燈最遠、丙最近，所以影長：甲＞乙＞丙。\n★ 點光源（路燈）：離光源愈遠，影子愈長。", "h": ["從路燈頂端經過人的頭頂畫直線到地面。", "比比看三個位置哪個離路燈最遠。"], "rep": true, "img": "s4-q2", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-3", "no": "3", "c": "k3", "src": "翰林 C卷 第7回 第 3 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "夏日中午在榕樹底下的地面，時常可看見好多個圓形的、明亮的、大小相當一致的光亮區域，則此光亮圓盤是何物的影子或像？", "o": ["太陽的像", "樹葉的像", "太陽的影子", "樹葉的影子"], "a": 0, "e": "樹葉間的小縫隙就像一個個「針孔」，太陽光穿過小孔，在地面形成太陽的實像。\n太陽是圓的，所以光斑是圓形；大小一致是因為樹葉離地面的距離差不多。\n★ 樹蔭下的圓形光斑＝太陽的針孔成像（倒立實像）。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-4", "no": "4", "c": "k9", "src": "翰林 C卷 第7回 第 4 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "下列何者無法用光直線前進的特性來說明？", "o": ["針孔成像", "影子的形成", "日晷的應用", "湖底看起來變淺"], "a": 3, "e": "針孔成像、影子、日晷都是光直線前進造成的。\n湖底看起來變淺，是光從水中進入空氣時發生「折射」，不是直進。\n★ 「看起來變淺、筷子折斷」都是折射。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-5", "no": "5", "c": "k3", "src": "翰林 C卷 第7回 第 5 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "右圖為針孔成像的實驗裝置，則紙屏上的成像圖案應為下列何者？", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 0, "e": "針孔成像一定是「倒立實像」（上下顛倒、左右相反）。\n物距 20 cm、像距 40 cm，像距比物距大，所以像會放大。\n四個圖中只有 (A) 是上下顛倒的燭火。\n★ 針孔成像：倒立實像；像長：物長＝像距：物距。", "h": [], "rep": true, "img": "s4-q5", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-6", "no": "6", "c": "k5", "src": "翰林 C卷 第7回 第 6 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "如右圖，甲、乙、丙是三條入射平面鏡的光線，則此三條入射光線的反射角大小關係為何？", "o": ["甲＞乙＞丙", "甲＝乙＝丙", "丙＞乙＞甲", "乙＞丙＞甲"], "a": 2, "e": "入射角、反射角都是光線與「法線」的夾角，不是與鏡面的夾角。\n圖中甲最接近法線、丙離法線最遠 → 入射角：丙＞乙＞甲。\n反射角＝入射角，所以反射角也是丙＞乙＞甲。\n★ 光線和鏡面的夾角愈小，入射角愈大。", "h": [], "rep": true, "img": "s4-q6", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-7", "no": "7", "c": "k5", "src": "翰林 C卷 第7回 第 7 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "先將鋁箔弄皺後再展開，則常光在凹凸不平的鋁箔面上反射時，其入射角和反射角的關係為何？", "o": ["入射角＞反射角", "入射角＜反射角", "入射角＝反射角", "視凹凸的情況而定"], "a": 2, "e": "鋁箔皺掉後表面凹凸不平，光會往各方向反射（漫射）。\n但每一小塊表面上的每一條光線，仍然遵守反射定律：入射角＝反射角。\n★ 漫射也遵守反射定律，只是各處法線方向不同。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-8", "no": "8", "c": "k2", "src": "翰林 C卷 第7回 第 8 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "夏天太陽由早晨到黃昏前，旗桿影子的移動方向及其長短如何變化？", "o": ["向西移動，逐漸變短", "向東移動，逐漸變長", "向東移動，先變小後變長", "向西移動，先變大後變短"], "a": 2, "e": "太陽從東方升起、西方落下，影子永遠在太陽的反方向。\n早上太陽在東 → 影子朝西；傍晚太陽在西 → 影子朝東 → 影子由西往東移動。\n中午太陽最高、影子最短，所以影長「先變短再變長」。\n★ 影子方向和太陽相反；太陽愈高，影子愈短。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-9", "no": "9", "c": "k7", "src": "翰林 C卷 第7回 第 9 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "在書局某個角落處，裝置一面大鏡子，以便增加視野，主要是利用光的何種性質，與使用何種鏡子？", "o": ["光的反射、凹面鏡", "光的折射、凹面鏡", "光的反射、凸面鏡", "光的折射、凸面鏡"], "a": 2, "e": "書局角落的大鏡子要「看得更廣」，用的是凸面鏡。\n凸面鏡是利用光的反射，成正立縮小虛像，視野範圍大。\n★ 凸面鏡：反射、正立縮小、視野大（轉角鏡、後照鏡）。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-10", "no": "10", "c": "k6", "src": "翰林 C卷 第7回 第 10 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "小劉在電梯中向西邊的鏡子移動，如右圖所示，則在甲、乙、丙三面鏡子中的像之移動方向，應該為下列何者？", "o": ["甲向東；乙向東；丙向東", "甲向東；乙向西；丙向東", "甲向西；乙向東；丙向西", "甲向西；乙向西；丙向東"], "a": 1, "e": "平面鏡成像：像和人對稱於鏡面，像距＝物距。\n甲是西邊的鏡子：小劉往西靠近甲 → 甲中的像也向東靠近鏡子。\n乙是北邊的鏡子：小劉沿鏡面方向往西走，像也跟著往西。\n丙是東邊的鏡子：小劉往西遠離丙 → 丙中的像往東遠離鏡子。\n★ 正對鏡子走：像朝你走來；沿著鏡面走：像跟你同方向走。", "h": [], "rep": true, "img": "s4-q10", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-11", "no": "11", "c": "k6", "src": "翰林 C卷 第7回 第 11 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "如右圖，S 為一點光源，L 為一不透明體，MN 為一平面鏡，則從 S 點發出的光線，經平面鏡反射後不可能通過下列哪一點？", "o": ["A", "B", "C", "D"], "a": 3, "e": "先畫出 S 對平面鏡 MN 的像 S'（對稱點）。\n反射光看起來都像從 S' 發出，所以反射光只會落在「S' 與 M、N 兩端連線」夾住的範圍內，而且路徑不能被 L 擋住。\n連線後 A、B、C 都在範圍內，D 在範圍外 → 不可能通過 D。\n★ 判斷反射光範圍：先找像點，再連鏡子的兩端。", "h": ["先畫出 S 在鏡中的像點 S'。", "從 S' 連到鏡子兩端 M、N，反射光只能在這兩條線之間。"], "rep": true, "img": "s4-q11", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-12", "no": "12", "c": "k6", "src": "翰林 C卷 第7回 第 12 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "琳琳站在直立的平面鏡前 5 公尺處，若將鏡子向琳琳平移 2 公尺，則琳琳和像之間的距離會變成多少公尺？", "o": ["3", "4.5", "6", "9"], "a": 2, "e": "原本人離鏡 5 公尺，鏡子向人移 2 公尺 → 人離鏡 3 公尺。\n像距＝物距＝3 公尺，所以人和像相距 3＋3＝6 公尺。\n★ 人和像的距離＝2 × 人到鏡子的距離。", "h": ["先算鏡子移動後，人離鏡子幾公尺。", "像距＝物距，人和像的距離要加起來。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-13", "no": "13", "c": "k7", "src": "翰林 C卷 第7回 第 13 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "如右圖所示，對著湯匙的凸面可以看到自己的影像在湯匙內出現，所看到成像的性質為下列何者？", "o": ["縮小虛像", "縮小實像", "放大虛像", "放大實像"], "a": 0, "e": "湯匙的「凸面」就是一面凸面鏡。\n凸面鏡不論物體在哪裡，都只會形成「正立縮小虛像」。\n★ 凸面鏡只有一種像：正立、縮小、虛像。（若是凹面近看，才是放大虛像）", "h": [], "rep": true, "img": "s4-q13", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-14", "no": "14", "c": "k8", "src": "翰林 C卷 第7回 第 14 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "當一束光線由空氣斜射入玻璃內，光線將產生偏折，試問其原因為何？", "o": ["光在空氣與玻璃中的行進速率不同", "光在空氣與玻璃中的頻率不同", "光在空氣與玻璃中的顏色不同", "光在空氣與玻璃中的停留時間不同"], "a": 0, "e": "光在不同介質中的「速率」不同，所以斜射進另一個介質時方向會偏折，這就是折射。\n光的頻率由光源決定，進入玻璃後不會改變；顏色也不變。\n★ 折射的原因：光速改變。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-15", "no": "15", "c": "k8", "src": "翰林 C卷 第7回 第 15 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "如右圖，當光線由介質甲中入射到介質乙中時，下列敘述何者錯誤？", "o": ["入射角大於折射角", "光在甲介質中的速率比較快", "若甲為空氣，則乙可能為水", "若甲為玻璃，則乙可能為水"], "a": 3, "e": "圖中折射角小於入射角 → 光偏向法線 → 乙介質中光速較慢。\n所以光在甲中比較快，甲可能是空氣、乙可能是水，(A)(B)(C) 正確。\n光速：空氣＞水＞玻璃。若甲是玻璃，乙要比玻璃更慢才行，水比玻璃快，所以 (D) 錯誤。\n★ 偏向法線 → 進入較慢的介質。", "h": [], "rep": true, "img": "s4-q15", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-16", "no": "16", "c": "k7", "src": "翰林 C卷 第7回 第 16 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "小喬買一個化妝盒，當化妝盒打開後，裡面附有一面鏡子，且鏡子可將臉部的像放大，則該鏡子應該是下列何者？", "o": ["凸面鏡", "凹面鏡", "平面鏡", "凹透鏡"], "a": 1, "e": "化妝鏡要讓臉「放大」，用凹面鏡。\n臉靠近凹面鏡（在焦點內）時，會成正立放大虛像。\n凸面鏡、平面鏡都不能放大；凹透鏡是透鏡，不是鏡子。\n★ 凹面鏡近看：正立放大虛像（化妝鏡、牙醫鏡）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-17", "no": "17", "c": "k9", "src": "翰林 C卷 第7回 第 17 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "有一種魚名叫水槍魚，牠常浮在水草邊，當牠在水中看見昆蟲飛過時，便能由口中射出一條水柱，將昆蟲射下來吃，若不考慮昆蟲的飛行，請問水槍魚想要射擊到目標，牠應該瞄準所見目標物的何方？", "o": ["目標物本體", "目標物上方", "目標物下方", "目標物左方"], "a": 2, "e": "昆蟲在空氣中，光從空氣進入水中會偏折，魚看到的是昆蟲「偏高」的虛像。\n所以魚要瞄準看到的位置的「下方」，才打得到真正的昆蟲。\n★ 從水中看空氣中的物體 → 看起來比較高；從空氣看水中 → 看起來比較淺（高）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-18", "no": "18", "c": "k8", "src": "翰林 C卷 第7回 第 18 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "一光線由介質甲射向介質乙，已知入射角為 50°，折射角為 30°，則其反射線與折射線的夾角為多少？", "o": ["20°", "60°", "80°", "100°"], "a": 3, "e": "反射角＝入射角＝50°。\n反射線和界面的夾角＝90°－50°＝40°；折射線和界面的夾角＝90°－30°＝60°。\n反射線與折射線的夾角＝40°＋60°＝100°（也可用 180°－50°－30°）。\n★ 反射線與折射線夾角＝180°－反射角－折射角。", "h": ["反射角等於入射角。", "畫出界面，用 180° 減去反射角和折射角。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-19", "no": "19", "c": "k8", "src": "翰林 C卷 第7回 第 19 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "如右圖，光線經過甲、乙、丙三層介質時發生折射，且角度 c＞a＞b，則光線在三介質中的速率大小關係，下列何者正確？", "o": ["甲＞乙＞丙", "甲＞丙＞乙", "丙＞甲＞乙", "丙＞乙＞甲"], "a": 2, "e": "光線和法線的夾角愈大，代表在該介質中光速愈快。\nc＞a＞b → 介質丙的角度最大、最快；乙的角度最小、最慢。\n所以速率：丙＞甲＞乙。\n★ 角度大＝速度快（離法線愈遠，光愈快）。", "h": [], "rep": true, "img": "s4-q19", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-20", "no": "20", "c": "k9", "src": "翰林 C卷 第7回 第 20 題", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "如右圖，把錢幣丟到杯中，若將水慢慢加入杯中，發現錢幣似乎慢慢地浮上來，請問水加愈多，我們從上方斜處看到的錢幣，和實際上錢幣的位置有何變化？", "o": ["水慢慢加入，兩者間的距離加大", "水慢慢加入，兩者間的距離縮小", "水的加入和兩者間的距離沒有關係", "這是光反射原理的應用"], "a": 0, "e": "錢幣反射的光從水中射入空氣會偏離法線，所以看到的錢幣（虛像）比實際位置高。\n水加得愈多，偏折的光路愈長，虛像被「抬高」得愈多，看到的位置和實際位置差距愈大。\n這是光的折射，不是反射。\n★ 水愈深，看起來淺得愈多。", "h": [], "rep": true, "img": "s4-q20", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-21", "no": "21", "c": "k11", "src": "翰林 A卷 第8回 第 1 題", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（4-4～4-5）", "pord": 2, "ctx": "", "fig": "", "q": "將一根蠟燭置於一個會聚透鏡的前面，若成像在該會聚透鏡的另一邊，則關於此成像的性質，下列何者一定正確？", "o": ["正立實像", "倒立實像", "縮小虛像", "放大虛像"], "a": 1, "e": "會聚透鏡就是凸透鏡。像成在透鏡的「另一側」，代表是光線真正會聚而成的實像。\n凸透鏡的實像一定是倒立的（大小則看物距，可放大也可縮小）。\n★ 凸透鏡：實像一定倒立、在鏡後；虛像一定正立、和物體同側。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-22", "no": "22", "c": "k11", "src": "翰林 A卷 第8回 第 2 題", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（4-4～4-5）", "pord": 2, "ctx": "", "fig": "", "q": "右圖為一物體的頂點發出的兩條光線經某透鏡折射後的情形，若該物體置於該透鏡前方 15 公分處，請問下列關於該透鏡的焦距與該物體成像的性質，何者正確？", "o": ["焦距小於 15 公分、縮小的虛像", "焦距小於 15 公分、放大的實像", "焦距大於 15 公分、縮小的虛像", "焦距大於 15 公分、放大的實像"], "a": 1, "e": "兩條光線折射後在透鏡另一側真的交在一起 → 是實像，而且像比物體大 → 放大實像。\n凸透鏡要成放大實像，物體要在 f～2f 之間，即 f＜15＜2f，所以焦距小於 15 公分（大於 7.5 公分）。\n★ 放大實像：f＜物距＜2f。", "h": [], "rep": true, "img": "s4-q22", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-23", "no": "23", "c": "k12", "src": "翰林 A卷 第8回 第 3 題", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（4-4～4-5）", "pord": 2, "ctx": "", "fig": "", "q": "士杰近來覺得視力變差，看遠方景物開始模糊不清。經過醫生檢查後告知士杰，他的水晶體焦距如右圖，請問士杰患有何種視力問題？應配戴何種鏡片做矯正？", "o": ["近視；凸透鏡", "近視；凹透鏡", "遠視；凸透鏡", "遠視；凹透鏡"], "a": 1, "e": "看遠方模糊、水晶體把光聚焦在視網膜「前方」→ 近視。\n近視是水晶體太凸、焦距太短，要戴能讓光發散的凹透鏡，把成像往後移到視網膜上。\n★ 近視：像在網膜前，戴凹透鏡；遠視：像在網膜後，戴凸透鏡。", "h": [], "rep": true, "img": "s4-q23", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-24", "no": "24", "c": "k14", "src": "翰林 A卷 第8回 第 4 題", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（4-4～4-5）", "pord": 2, "ctx": "", "fig": "", "q": "小新參加密室解謎活動，某關卡給了一個紅、藍、綠、白畫成的「日」字型圖案（底紙為黑色），如右圖所示。關主指示：在暗室中分別先利用紅光照射後再改用藍光照射此圖案，先後所顯示的數字，即為此關卡的密碼。請問正確密碼為何？", "o": ["52", "43", "34", "28"], "a": 1, "e": "不透明物體只反射和自己同色的光，白色反射所有色光，其他吸收變黑。\n紅光照射：紅色和白色的部分亮起來（紅色），排出的形狀是「4」。\n藍光照射：藍色和白色的部分亮起來（藍色），排出的形狀是「3」。\n所以密碼是 43。\n★ 色光照物體：同色或白色會亮，其他變黑。", "h": ["紅光下，只有紅色和白色的區塊會亮。", "把會亮的區塊連起來看看是什麼數字。"], "rep": true, "img": "s4-q24", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-25", "no": "25", "c": "k11", "src": "翰林 A卷 第8回 第 5 題", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（4-4～4-5）", "pord": 2, "ctx": "", "fig": "", "q": "一般為了看清楚物體的微小部分，會使用放大鏡來輔助，則使用放大鏡時應該將物體擺放在何處？", "o": ["焦點內", "一倍焦距與兩倍焦距間", "兩倍焦距上", "兩倍焦距外"], "a": 0, "e": "放大鏡是凸透鏡，物體放在焦點內，從另一側看會看到正立放大虛像。\n放在焦點外會形成倒立實像，就不是放大鏡的用法了。\n★ 放大鏡：物體在焦點內 → 正立放大虛像。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-26", "no": "26", "c": "k11", "src": "翰林 A卷 第8回 第 6 題", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（4-4～4-5）", "pord": 2, "ctx": "", "fig": "", "q": "右圖為凸透鏡成像實驗裝置。當幻燈片與透鏡的距離落在兩倍焦距與一倍焦距之間時，則在紙屏上所呈現的像是哪一個？", "o": ["正立縮小圖像", "倒立放大圖像", "正立放大圖像", "倒立縮小圖像"], "a": 1, "e": "幻燈片放在 f～2f 之間，凸透鏡會在 2f 外成「倒立放大實像」。\n倒立是上下顛倒、左右也相反。\n★ 投影機、幻燈機：物在 f～2f，成倒立放大實像。", "h": [], "rep": true, "img": "s4-q26", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-27", "no": "27", "c": "k14", "src": "翰林 A卷 第8回 第 7 題", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（4-4～4-5）", "pord": 2, "ctx": "", "fig": "", "q": "對於白色物體（甲）與黑色物體（乙）的敘述，下列何者正確？", "o": ["甲吸收各色光，乙反射各色光", "甲透射各色光，乙吸收各色光", "甲反射各色光，乙吸收各色光", "甲反射各色光，乙透射各色光"], "a": 2, "e": "白色物體會反射所有色光，所以看起來是白色。\n黑色物體會吸收所有色光，沒有光反射進眼睛，所以看起來是黑色。\n★ 白＝全部反射；黑＝全部吸收。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-28", "no": "28", "c": "k14", "src": "翰林 A卷 第8回 第 17 題", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（4-4～4-5）", "pord": 2, "ctx": "", "fig": "", "q": "日光照射一張圖，圖中有紅色、綠色、藍色、白色、黑色的圖案，若戴著紅色鏡片的眼鏡來看圖時，畫面中共會出現哪些顏色？", "o": ["僅紅色", "紅色、黑色", "紅色、黑色、紫色", "紅色、黑色、黃色"], "a": 1, "e": "紅色鏡片只讓紅光通過。\n紅色、白色的圖案有反射紅光 → 透過鏡片看到紅色。\n綠色、藍色只反射綠光、藍光，被鏡片擋住 → 黑色；黑色本來就是黑色。\n所以只會看到紅色和黑色。\n★ 戴有色鏡片：只剩該顏色和黑色。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-29", "no": "29", "c": "k11", "src": "翰林 A卷 第8回 活用題 3", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（4-4～4-5）", "pord": 2, "ctx": "", "fig": "", "q": "如右圖，若將凸透鏡的上半部用不透光東西遮住，則對於透鏡的成像有何影響？", "o": ["不會有任何影響", "只有上半部會成像", "只有下半部會成像", "全部都會成像但是亮度變暗"], "a": 3, "e": "透鏡上的每一部分都能讓物體的光折射成完整的像。\n遮住上半部，只是通過透鏡的光變少，像仍然完整，只是變暗。\n★ 遮住透鏡一部分：像完整、變暗；形狀、大小、位置都不變。", "h": [], "rep": true, "img": "s4-q29", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-30", "no": "30", "c": "k10", "src": "翰林 A卷 第8回 活用題 5", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（4-4～4-5）", "pord": 2, "ctx": "", "fig": "", "q": "心兒在暗房中，以右圖的裝置，測定燭火成像於紙屏上時，煙火至透鏡距離 a（物距）與紙屏至透鏡距離 b（像距）的關係如下表。試回答 5、6. 題：當太陽光通過凸透鏡後，紙屏上可以生成一亮點，此時像距 b 為多少公分？", "o": ["10", "20", "30", "40"], "a": 1, "e": "表中 a＝40 時 b＝40，物距＝像距 → 物體在 2 倍焦距上，所以 2f＝40，f＝20 cm。\n太陽光很遠，可視為平行光，經凸透鏡會聚在焦點上，所以像距＝f＝20 cm。\n★ 物距＝像距的地方就是 2f；平行光聚在焦點。", "h": ["找出表中物距和像距相等的那一組。", "那個距離是 2 倍焦距，太陽光會聚在 1 倍焦距處。"], "rep": true, "img": "s4-q30", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-31", "no": "31", "c": "k14", "src": "金安 A卷 第9次練習 第 1 題", "st": "考卷", "pk": "ja-9", "pname": "金安 A卷・第9次練習（第3～4單元）", "pord": 6, "ctx": "", "fig": "", "q": "利用紅、綠、藍三種色光照在不同物體的表面，請問下列哪一個物體表面為白色？", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 1, "e": "白色物體會反射所有色光：紅光照到反射紅光、綠光反射綠光、藍光反射藍光。\n圖 (B) 中三種色光照到物體後全部被反射出來，就是白色物體。\n★ 白色物體：照什麼光就反射什麼光。", "h": [], "rep": true, "img": "s4-q31", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-32", "no": "32", "c": "k14", "src": "金安 A卷 第9次練習 第 2 題", "st": "考卷", "pk": "ja-9", "pname": "金安 A卷・第9次練習（第3～4單元）", "pord": 6, "ctx": "", "fig": "", "q": "小雅晚上到麵店吃蔬菜麵，老闆用綠色的碗裝入白色的麵與綠色的蔬菜。當小雅要開始吃的時候，突然停電，整個店裡漆黑一片，老闆趕緊打開紅色的燈光，則此時小雅看往蔬菜麵，會看到下列何者？", "o": ["紅色碗、白色麵、綠色蔬菜", "紅色碗、白色麵、黑色蔬菜", "黑色碗、紅色麵、黑色蔬菜", "黑色碗、黑色麵、黑色蔬菜"], "a": 2, "e": "紅光下：綠色碗只能反射綠光，紅光被吸收 → 黑色。\n白色麵會反射紅光 → 紅色。綠色蔬菜也吸收紅光 → 黑色。\n★ 單色光照射：白色物體變成該色光的顏色，其他顏色的物體變黑。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-33", "no": "33", "c": "k11", "src": "金安 A卷 第9次練習 第 4 題", "st": "考卷", "pk": "ja-9", "pname": "金安 A卷・第9次練習（第3～4單元）", "pord": 6, "ctx": "", "fig": "", "q": "在錶玻璃的凹面內倒入一些水，再將錶玻璃放在中文字上，觀察結果如右圖所示，下列敘述何者錯誤？", "o": ["成像效果相當於平凸透鏡", "所成的像為實像", "印有中文的紙張位於焦點內", "將裝水的錶玻璃稍微提高，仍會有放大效果"], "a": 1, "e": "錶玻璃裝水後，中間厚、邊緣薄，就像一個平凸透鏡，(A) 正確。\n從上方看到字變大且正立 → 是「正立放大虛像」，不是實像，所以 (B) 錯誤。\n字在透鏡的焦點內才會有正立放大虛像；稍微提高，只要還在焦點內，仍然有放大效果。\n★ 透過透鏡直接看到正立放大的字 → 虛像。", "h": [], "rep": false, "img": "s4-q33", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-34", "no": "34", "c": "k6", "src": "金安 A卷 第9次練習 第 6 題", "st": "考卷", "pk": "ja-9", "pname": "金安 A卷・第9次練習（第3～4單元）", "pord": 6, "ctx": "", "fig": "", "q": "金華站在百貨公司的試衣鏡前 0.5 公尺處照鏡子，則下列敘述何者正確？", "o": ["金華會發現自己在鏡中上下顛倒", "鏡子內的像大小和金華離鏡子的遠近有關", "金華在鏡子所看到的像為實像", "鏡中的像和金華相距 1.0 公尺"], "a": 3, "e": "平面鏡成像：正立、等大、虛像，像的大小和離鏡遠近無關。\n像距＝物距＝0.5 公尺，所以人和像相距 0.5＋0.5＝1.0 公尺。\n★ 平面鏡：人和像的距離是人到鏡子距離的 2 倍。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-35", "no": "35", "c": "k10", "src": "金安 A卷 第9次練習 第 7 題", "st": "考卷", "pk": "ja-9", "pname": "金安 A卷・第9次練習（第3～4單元）", "pord": 6, "ctx": "", "fig": "", "q": "右圖所示為光線經過凹透鏡時偏折的情形，則虛焦點在圖中的哪一點上？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "凹透鏡會讓平行主軸的光線發散。\n把折射後的光線往回（往左）延長，延長線和主軸的交點就是虛焦點，在圖中的丙點。\n★ 凹透鏡的焦點是「延長線」交出來的虛焦點。", "h": [], "rep": false, "img": "s4-q35", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-36", "no": "36", "c": "k13", "src": "金安 A卷 第9次練習 第 8 題", "st": "考卷", "pk": "ja-9", "pname": "金安 A卷・第9次練習（第3～4單元）", "pord": 6, "ctx": "", "fig": "", "q": "如右圖所示，某玻璃柱體在太陽光通過後，會產生不同顏色的光線，其原因不包括下列何者？", "o": ["光速改變", "折射現象", "太陽光是混合光", "太陽光是單一色光"], "a": 3, "e": "太陽光是由多種色光混合成的白光。\n進入玻璃時各色光的速率改變程度不同，偏折角度不同，於是分散開來，這就是色散。\n所以原因「不包括」太陽光是單一色光。\n★ 色散的原因：各色光在玻璃中速率不同、偏折不同。", "h": [], "rep": true, "img": "s4-q36", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-37", "no": "37", "c": "k6", "src": "金安 A卷 第9次練習 第 11 題", "st": "考卷", "pk": "ja-9", "pname": "金安 A卷・第9次練習（第3～4單元）", "pord": 6, "ctx": "", "fig": "", "q": "右圖為行駛在高速公路上的一輛汽車的車牌，在這部車前方一段距離的汽車車主，由後視鏡所看到的車牌成像為何？（車牌號碼為 7456-NO）", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 1, "e": "前車車主看的是後方車子在後照鏡中的像，鏡中的像左右相反。\n車牌「7456－NO」在鏡中會變成順序顛倒、每個字也左右翻轉的樣子，就是圖 (B)。\n★ 鏡中的像：左右相反（上下不變）。", "h": [], "rep": true, "img": "s4-q37", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-38", "no": "38", "c": "k9", "src": "金安 A卷 第9次練習 第 14 題", "st": "考卷", "pk": "ja-9", "pname": "金安 A卷・第9次練習（第3～4單元）", "pord": 6, "ctx": "", "fig": "", "q": "在裝有水的話魚缸中，要用雷射光筆照射黑色圓點，如右圖，則應標注「眼睛所看見黑色圓點」的哪一個方向瞄準，才可以命中黑色圓點？", "o": ["甲（上方）", "乙（正對）", "丙（下方）", "丁（側面）"], "a": 1, "e": "我們看到的黑點，是黑點的光經水面折射後進入眼睛的方向。\n光的路徑可以反過來走（光路可逆），所以雷射光只要沿著「看到黑點的方向」射回去，就會沿原路徑折射回到黑點。\n★ 光路可逆：看到哪裡就瞄哪裡（用光照的話）。", "h": [], "rep": true, "img": "s4-q38", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-39", "no": "39", "c": "k11", "src": "金安 A卷 第9次練習 第 15 題", "st": "考卷", "pk": "ja-9", "pname": "金安 A卷・第9次練習（第3～4單元）", "pord": 6, "ctx": "", "fig": "", "q": "以焦距為 20 公分的凹透鏡觀察紙上一數字「7」，若原圖形大小如右圖，則在物距 15 公分的距離可能觀察到什麼結果？", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 2, "e": "凹透鏡不論物體放在哪裡，只能成「正立縮小虛像」。\n四個圖中，只有丙是正立而且比原來的「7」小。\n★ 凹透鏡只有一種像：正立、縮小、虛像。", "h": [], "rep": false, "img": "s4-q39", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-40", "no": "40", "c": "k8", "src": "金安 A卷 第9次練習 第 17 題", "st": "考卷", "pk": "ja-9", "pname": "金安 A卷・第9次練習（第3～4單元）", "pord": 6, "ctx": "", "fig": "", "q": "如右圖所示，當光線從甲介質進入到乙介質，若已知光在甲介質中的速率比在乙介質中還要快，則折射光將沿哪一條光線前進才合理？", "o": ["A", "B", "C", "D"], "a": 2, "e": "光在甲中比較快、在乙中比較慢 → 進入乙時會偏向法線，折射角小於入射角。\n光線穿過界面後應該在法線的另一側，而且比入射時更靠近法線，就是 C。\nA 是反射線；B、D 都沒有偏向法線，不合理。\n★ 快 → 慢：偏向法線。", "h": [], "rep": true, "img": "s4-q40", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-41", "no": "41", "c": "k1", "src": "講義 p.123", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "以下光線中何者可正確顯示如何看見一朵花？", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 2, "e": "花朵本身不會發光，是太陽光照到花朵，花朵把光反射進入我們的眼睛，我們才看見花。\n光不是從眼睛射出去的。圖 (C) 是太陽光射向花，再由花反射到眼睛。\n★ 看到不發光的物體：光源 → 物體反射 → 眼睛。", "h": [], "rep": false, "img": "s4-q41", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-42", "no": "42", "c": "k9", "src": "講義 p.123", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列何者不是光沿直線前進的例子？", "o": ["立竿見影", "皮影戲", "鑿壁引光", "閃爍的星光"], "a": 3, "e": "立竿見影、皮影戲都是影子，鑿壁引光是光沿直線穿過牆洞，都是光的直進。\n星光閃爍是星光穿過不穩定的大氣層時不斷折射、偏折，屬於折射。\n★ 星星閃爍、海市蜃樓都是大氣折射。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-43", "no": "43", "c": "k2", "src": "講義 p.123", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "如右圖，利用一不透明紙板在光源前形成陰影於紙屏上，下列哪一種方法可以使影子變大？", "o": ["光源靠近障礙物", "紙屏向光源移動", "障礙物遠離光影", "將光源換成較大燈泡"], "a": 0, "e": "點光源造成的影子：障礙物愈靠近光源（或光源靠近障礙物），影子愈大。\n紙屏移向光源、障礙物遠離光源都會讓影子變小。\n換成大燈泡只會讓影子邊緣出現半影，並不是把影子變大。\n★ 障礙物離光源愈近、離屏愈遠，影子愈大。", "h": [], "rep": false, "img": "s4-q43", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-44", "no": "44", "c": "k3", "src": "講義 p.123", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "右圖為針孔成像的實驗裝置，則紙屏上的成像圖案為下列何者？", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 1, "e": "針孔成像是倒立實像。物距 15 cm、像距 30 cm，像距比物距大 → 放大。\n所以紙屏上是「倒立放大」的燭火，圖 (B)。\n★ 像長：物長＝像距：物距。", "h": [], "rep": false, "img": "s4-q44", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-45", "no": "45", "c": "k4", "src": "講義 p.123", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "光在真空、空氣、水、玻璃四者中的傳播速率大小順序為何？", "o": ["空氣＞水＞玻璃＞真空", "空氣＞真空＞玻璃＞水", "玻璃＞水＞空氣＞真空", "真空＞空氣＞水＞玻璃"], "a": 3, "e": "光在真空中最快，約 3×10⁸ m/s。\n介質愈「密」，光愈慢：真空＞空氣＞水＞玻璃。\n★ 光速：真空＞空氣＞水＞玻璃（＞鑽石）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-46", "no": "46", "c": "k5", "src": "講義 p.133", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "小甫用雷射筆對著平面鏡作反射定律的實驗，如右圖所示。雷射筆發出的光線經平面鏡反射後，其行進的路線為圖中的哪一條線？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "反射定律：反射光和入射光分別在法線兩側，且反射角＝入射角。\n雷射筆從法線上方左側斜射，反射光應該在法線另一側，以相同的角度離開鏡面，就是丙。\n★ 反射線和入射線「對稱於法線」。", "h": [], "rep": false, "img": "s4-q46", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-47", "no": "47", "c": "k5", "src": "講義 p.133", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "如右圖所示，有一束光線由甲點發射，經過乙點後垂直射至平面鏡上的戊點，則反射的光線所經過的路徑應為下列何者？", "o": ["戊→乙", "戊→丙", "戊→丁", "戊→己"], "a": 0, "e": "光線垂直射到平面鏡時，入射角＝0°，反射角也＝0°。\n所以反射光會沿原路徑反彈回去：戊 → 乙 → 甲。\n★ 垂直入射 → 原路反射。", "h": [], "rep": false, "img": "s4-q47", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-48", "no": "48", "c": "k6", "src": "講義 p.133", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "人向平面鏡移近 1 公尺時，下列敘述何者正確？", "o": ["像離開鏡面後退 1 公尺", "人與像的距離縮短 1 公尺", "人與像的距離縮短 2 公尺", "人與像的距離不變"], "a": 2, "e": "人走近鏡子 1 公尺，像也同時走近鏡子 1 公尺。\n所以人和像的距離縮短 1＋1＝2 公尺。\n★ 人移動 x，人和像的距離改變 2x。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-49", "no": "49", "c": "k6", "src": "講義 p.134", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "右圖平面鏡前透明投影片上的「P」字，從鏡前的人看來，「P」在鏡中的像為下列何者？", "o": ["P", "q", "b", "d"], "a": 0, "e": "投影片是透明的，人從鏡前透過投影片看鏡子。\n鏡中的像和投影片對稱於鏡面，從人的方向看過去，字的左右沒有改變，所以看到的還是「P」。\n★ 透明片上的字：從同一側看鏡中的像，和直接看透明片的樣子相同。", "h": [], "rep": false, "img": "s4-q49", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-50", "no": "50", "c": "k7", "src": "講義 p.134", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列何者不是凹面鏡的應用？", "o": ["太陽爐", "化妝鏡", "探照燈", "公車後照鏡"], "a": 3, "e": "凹面鏡能聚光：太陽爐、化妝鏡（放大）、探照燈（光源在焦點）都是凹面鏡。\n公車後照鏡要看大範圍，是凸面鏡。\n★ 凹面鏡：聚光、放大；凸面鏡：視野大。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-51", "no": "51", "c": "k7", "src": "講義 p.134", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "胖虎每次去抬午餐時，會在行政樓前看到一面鏡子，每個同學的像正立變小，也可以看到比較大的區域範圍，此鏡應該是下列何者？", "o": ["平面鏡", "凸面鏡", "凹面鏡", "哈哈鏡"], "a": 1, "e": "像「正立變小」又能看到「比較大的範圍」，是凸面鏡的特色。\n這種鏡子常放在轉角、行政樓前或停車場出口。\n★ 凸面鏡：正立縮小虛像、視野大。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-52", "no": "52", "c": "k13", "src": "講義 p.157", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "太陽光入射三稜鏡後會發生色散，主要原因是各種色光在玻璃中的哪一種性質不同？", "o": ["速率", "振幅", "頻率", "波長"], "a": 0, "e": "太陽光進入三稜鏡時，各種色光在玻璃中的「速率」不同，偏折程度就不同，於是分開形成色散。\n★ 色散的原因：不同色光在玻璃中的光速不同。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-53", "no": "53", "c": "k13", "src": "講義 p.157", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "太陽光經過三稜鏡之後，將產生色散的結果，則下列敘述何者錯誤？", "o": ["色散現象是由牛頓提出的", "紅色光在三稜鏡中傳播速率最快，波長最短", "色散之後，每種色光偏折角度不同", "表示白光是由不同顏色的光混合而成"], "a": 1, "e": "紅光在玻璃中速率最快、偏折最小，而且紅光的波長「最長」，不是最短，所以 (B) 錯誤。\n色散由牛頓用三稜鏡實驗提出，證明白光是多種色光混合的，各色光偏折角度不同。\n★ 紅光：偏折最小、波長最長；紫光：偏折最大、波長最短。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-54", "no": "54", "c": "k14", "src": "講義 p.157", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "將光的三原色紅、綠、藍三種色光同時照在白紙上，則下列敘述何者正確？", "o": ["三種色光交會處為黑色", "綠光、紅光交會處為青色", "綠光、藍光交會處為紫色", "紅光和藍光的交會處為洋紅色"], "a": 3, "e": "色光混合：紅＋綠＝黃、綠＋藍＝青、紅＋藍＝洋紅、紅＋綠＋藍＝白。\n所以三種色光交會處是白色，(D) 紅光和藍光交會處為洋紅色正確。\n★ 色光三原色混合：紅綠黃、綠藍青、紅藍洋紅、三色變白。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-55", "no": "55", "c": "k14", "src": "講義 p.162", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "有白光、紅光、綠光及藍光四種不同的色光照射在紅色玻璃片上，若虛線表示無透射光線，則透過紅色玻璃之光線最接近下列何種情況？", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 2, "e": "紅色玻璃片只讓紅光通過，其他色光被吸收。\n白光裡含有紅光 → 透出紅光；紅光 → 透出紅光；綠光、藍光 → 全被吸收，沒有光透出（虛線）。\n這就是圖 (C)。\n★ 有色透明體：只讓同色光通過。", "h": [], "rep": false, "img": "s4-q55", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-56", "no": "56", "c": "k14", "src": "講義 p.162", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "如右圖所示，在白光的照射下，阿舍所看見圖卡中藍色、紅色、綠色、白色部分的面積分別為 8 cm²、4 cm²、2 cm²、2 cm²。用下列哪一種顏色的光照射圖卡，阿舍最可能看見黑色部分的面積為 10 cm²？", "o": ["紅光", "藍光", "綠光", "白光"], "a": 0, "e": "用紅光照：紅色和白色部分反射紅光（看起來紅色），藍色、綠色吸收紅光變黑。\n黑色面積＝藍 8＋綠 2＝10 cm²，符合題目。\n用藍光：黑色＝紅 4＋綠 2＝6；用綠光：黑色＝藍 8＋紅 4＝12；白光沒有黑色。\n★ 單色光照射：和光不同色的部分都會變黑。", "h": ["每種色光照射時，哪些顏色會變黑？", "把變黑的面積加起來，看哪一個是 10 cm²。"], "rep": false, "img": "s4-q56", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-57", "no": "57", "c": "k3", "src": "講義 p.162", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列選項中的四個活動，光線經過「　」中的裝置後，哪一個不會改變光的傳播方向？", "o": ["利用「針孔」成像觀察日食", "利用「放大鏡」觀察校園中的花朵", "利用「汽車後照鏡」觀察後方的車輛位置", "利用「三稜鏡」將陽光分散成七種不同顏色的光"], "a": 0, "e": "針孔成像是光沿直線穿過小孔，不改變光的傳播方向。\n放大鏡（折射）、後照鏡（反射）、三稜鏡（折射）都會改變光的方向。\n★ 針孔成像只靠直進，不偏折。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-58", "no": "58", "c": "k3", "src": "講義 p.163", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "如右圖所示，此為大雄做針孔成像的實驗裝置，若燭火的長度為 2 cm，則下列敘述何者錯誤？", "o": ["紙屏會生成上下顛倒的像", "紙屏會生成左右相反的像", "紙屏上的燭火圖像為 4 cm", "將針孔挖大時，會使紙屏成像更加清楚"], "a": 3, "e": "針孔成像是倒立實像：上下顛倒、左右相反，(A)(B) 正確。\n像長＝2 cm × 20÷10＝4 cm，(C) 正確。\n針孔挖大時，通過的光束變粗、像互相重疊，像會變亮但變模糊，所以 (D) 錯誤。\n★ 針孔愈大：愈亮、愈模糊。", "h": ["像長：物長＝像距：物距。"], "rep": false, "img": "s4-q58", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-59", "no": "59", "c": "k12", "src": "講義 p.163", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "有關光學儀器的敘述，下列何者錯誤？", "o": ["照相機所成的像為縮小的倒立實像", "眼睛的水晶體相當於照相機裡的凸面鏡", "放大鏡是一種凸透鏡的應用", "使用放大鏡時，將物體放在焦點內，可得放大虛像"], "a": 1, "e": "眼睛的水晶體相當於照相機的「凸透鏡」（鏡頭），不是凸面鏡，所以 (B) 錯誤。\n照相機成倒立縮小實像；放大鏡是凸透鏡，物體放在焦點內得到正立放大虛像。\n★ 鏡＝反射（面鏡）；透鏡＝折射。水晶體是透鏡。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-60", "no": "60", "c": "k7", "src": "講義 p.164", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "在日常生活中，下列何種狀況沒有光的折射現象？", "o": ["戴近視眼鏡所看到的影像", "使用放大鏡觀察螞蟻的活動", "站在泳池邊看池底，有變淺的感覺", "汽車兩旁的凸面後照鏡，可看到兩旁的來車"], "a": 3, "e": "近視眼鏡（凹透鏡）、放大鏡（凸透鏡）、池底變淺都和折射有關。\n凸面後照鏡是利用光的「反射」，沒有折射。\n★ 面鏡 → 反射；透鏡、水 → 折射。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-61", "no": "61", "c": "k11", "src": "講義 p.164", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "實驗數據：p（公分）＝24、28、30、40、60、90、120 時，q（公分）依序＝120、70、59、40、30、26、24。", "fig": "", "q": "達達用焦距為 20 公分的透鏡做成像實驗，裝置如右圖。p 為燭火至透鏡的距離，q 為紙屏上得到最清晰圖像時，紙屏至透鏡的距離。調整 p 值測量相對應的 q 值，結果如下表。當 p＝29 公分時，在紙屏上所成之像為下列何者？", "o": ["倒立縮小實像", "正立縮小實像", "倒立放大實像", "正立放大實像"], "a": 2, "e": "焦距 20 公分，2f＝40 公分。p＝29 公分介於 f（20）和 2f（40）之間。\n物體在 f～2f 之間，凸透鏡成「倒立放大實像」，從表中 p＝28 時 q＝70、p＝30 時 q＝59 也可看出，像距比物距大，像是放大的。\n★ f＜物距＜2f → 倒立放大實像。", "h": ["先算出 2 倍焦距是多少。", "29 公分落在哪一個範圍？"], "rep": false, "img": "s4-q61", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-62", "no": "62", "c": "k14", "src": "講義 p.164", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "阿秀身穿勁裝參加舞會，當舞會照射紅光時，阿秀的勁裝為紅衣紅裙，當舞會的燈光改照射藍光時，阿秀的勁裝變為藍衣黑裙，則阿秀是穿著什麼顏色的勁裝去參加舞會的？", "o": ["白衣綠裙", "白衣紅裙", "白衣黑裙", "黑衣黑裙"], "a": 1, "e": "紅光下衣、裙都是紅色 → 衣、裙都能反射紅光。\n藍光下衣服是藍色（能反射藍光）、裙子變黑（不能反射藍光）。\n能同時反射紅光和藍光的衣服 → 白色；只能反射紅光的裙子 → 紅色。所以是白衣紅裙。\n★ 用不同色光試，找出物體「能反射哪些光」。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-63", "no": "63", "c": "k12", "src": "講義 p.164", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "在某部卡通影片中出現以下的劇情：「哈利被恐龍抓住，情急之下他拿下近視眼鏡來聚焦太陽光，灼傷恐龍，並趁機會逃走……」。有關「他拿下近視眼鏡來聚焦太陽光」的敘述，下列何者正確？", "o": ["近視眼鏡是凸面鏡，在空氣中可以聚集太陽光，故此劇情符合科學原理", "近視眼鏡是凹面鏡，在空氣中可以聚集太陽光，故此劇情符合科學原理", "近視眼鏡是凸透鏡，在空氣中無法聚集太陽光，故此劇情不符合科學原理", "近視眼鏡是凹透鏡，在空氣中無法聚集太陽光，故此劇情不符合科學原理"], "a": 3, "e": "近視眼鏡是「凹透鏡」，會讓光線發散，在空氣中無法把太陽光會聚到一點。\n所以用近視眼鏡聚光生火不符合科學原理。（遠視眼鏡、放大鏡是凸透鏡才可以）\n★ 凹透鏡：發散光線，不能聚光。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-64", "no": "64", "c": "k9", "src": "自修 p.154", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列何者與光的直進性質無關？", "o": ["以單眼瞄準對齊教室內桌子", "影子的形成", "由空氣中看見池水中的魚", "針孔成像"], "a": 2, "e": "單眼瞄準、影子、針孔成像都是光的直進。\n從空氣中看池水中的魚，光從水進入空氣發生折射，和直進無關。\n★ 跨越兩種介質的現象 → 通常是折射。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-65", "no": "65", "c": "k1", "src": "自修 p.154", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "黑暗無月光的夜裡，甲在亮室中近窗戶處，乙在暗室內面對窗戶距窗戶 3 公尺，兩屋窗戶相對相距 2 公尺，則甲是否可看見乙，乙是否可看見甲，依次為何？", "o": ["是、是", "是、否", "否、是", "否、否"], "a": 2, "e": "我們要看見物體，物體的光要進入眼睛。\n甲在亮室，身上有光反射出去，乙看得見甲；乙在暗室，沒有光照到乙，乙身上沒有光反射出來，甲看不見乙。\n所以甲看不見乙（否）、乙看得見甲（是）。\n★ 看見物體的條件：物體發光或反射光進入眼睛。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-66", "no": "66", "c": "k3", "src": "自修 p.154", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "夏日中午在榕樹底的地面，時常可看見好多個圓形的、明亮的、大小相當一致的光亮區域，則此光亮圓盤是何物的影子或像？", "o": ["太陽的像", "樹葉的像", "太陽的影子", "樹葉的影子"], "a": 0, "e": "樹葉間的小縫隙相當於針孔，太陽光穿過後在地面形成太陽的實像。\n太陽是圓形，所以地上的光斑都是圓形。\n★ 樹蔭下的圓形光斑＝太陽的像，不是影子。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-67", "no": "67", "c": "k3", "src": "自修 p.154", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "針孔成像實驗，在暗室中以硬紙板中間挖一小孔，直立於桌面，白色牆壁作為屏，燭火立於針孔前方 20 cm 處，針孔距牆 15 cm，如右圖，則下列敘述何者正確？", "o": ["針孔愈大，成像愈清楚", "室內燈打開，則無法看到牆上的燭火像", "牆上燭火像為正立實像", "蠟燭向針孔移近，牆上燭火像長度變小"], "a": 1, "e": "針孔愈大，像愈亮但愈模糊，(A) 錯。\n燭火像很暗，室內燈打開時，牆上被照亮，就看不到燭火像了，(B) 正確。\n針孔成像是倒立實像，(C) 錯；蠟燭靠近針孔，物距變小，像會變大，(D) 錯。\n★ 針孔成像要在暗室才看得清楚。", "h": [], "rep": false, "img": "s4-q67", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-68", "no": "68", "c": "k2", "src": "自修 p.155", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "夏日中午，身高為 171 cm 的孟倫站立時，地上影長只有 19 cm，則其旁有一棵椰子樹，地面樹影長度為 57 cm，則此椰子樹的高度約為多少 cm？", "o": ["342", "513", "684", "855"], "a": 1, "e": "太陽光是平行光，同一時間、同一地點，物高和影長成正比。\n171÷19＝9，表示物高是影長的 9 倍 → 樹高＝57×9＝513 cm。\n★ 太陽光下：物高：影長＝固定比例。", "h": ["先算孟倫的身高是影長的幾倍。", "樹也用同樣的倍數。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-69", "no": "69", "c": "k1", "src": "自修 p.155", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "(甲)以單眼瞄準射箭靶；(乙)日偏食；(丙)穿衣可以蔽體；(丁)泳池深度看起來較實際的淺，以上與光線直進性質有關的共有哪幾項？", "o": ["(甲)(乙)(丙)", "(甲)(乙)(丁)", "(甲)(丙)(丁)", "(乙)(丙)(丁)"], "a": 0, "e": "單眼瞄準、日偏食、穿衣蔽體（光不能穿過不透明物）都是光的直進。\n泳池看起來變淺是光的折射。\n所以有關的是甲、乙、丙。\n★ 日食、月食、影子、蔽體 → 直進。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-70", "no": "70", "c": "k2", "src": "自修 p.155", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "夏日晴天的下午，甲、乙、丙三人站立於操場，同一時刻三人的影長分別為 42.8 cm、45.5 cm 和 47.7 cm，則下列敘述何者正確？", "o": ["甲的身高為 171.2 cm", "三人中，以丙的身高最高", "影長與身高無關", "地面影子區域的草等景物因完全黑暗而看不到"], "a": 1, "e": "太陽光是平行光，同一時刻身高和影長成正比，影子最長的丙最高。\n只知道影長不知道比例，無法算出甲的身高；影子區域仍有周圍的散射光，草還是看得到。\n★ 平行光下：影子愈長，身高愈高。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-71", "no": "71", "c": "k2", "src": "自修 p.155", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "在地面上相距 1 公尺、長度相等的直立竹竿，在同一個路燈照射下形成右圖的影長，則路燈與竹竿甲、乙、丙之距離，依次分別為 S_甲、S_乙、S_丙，則下列何者正確？", "o": ["S_甲 > S_乙 > S_丙", "S_乙 > S_丙 > S_甲", "S_丙 > S_乙 > S_甲", "S_甲 > S_丙 > S_乙"], "a": 2, "e": "點光源（路燈）下，等高的竹竿離路燈愈遠，影子愈長。\n圖中甲的影子最短 → 離路燈最近；丙最長 → 最遠。\n所以 S丙＞S乙＞S甲。\n★ 路燈下：影長愈長，離路燈愈遠。", "h": [], "rep": false, "img": "s4-q71", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-72", "no": "72", "c": "k3", "src": "自修 p.155", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "將針孔成像的針孔挖成較大的洞，則紙屏上的像將如何？", "o": ["像長度變長", "像長度變小", "像更清楚", "無法成清晰的像"], "a": 3, "e": "針孔挖大後，就像很多個小針孔各自成像，彼此重疊，像會變亮但變得模糊，無法成清晰的像。\n★ 針孔愈大愈模糊；針孔太大就只剩一團光。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-73", "no": "73", "c": "k3", "src": "自修 p.155", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "針孔成像實驗可以說明光線具有下列何項性質？", "o": ["可在真空中傳播", "可在空氣中傳播", "為直線傳播", "具有繞射"], "a": 2, "e": "針孔成像能成倒立的像，是因為光從物體上、下兩端沿直線穿過小孔後交叉。\n所以它說明光的直線傳播。\n★ 針孔成像、影子、日食 → 光的直進。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-74", "no": "74", "c": "k3", "src": "自修 p.155", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "如右圖，以一 Q 字形發光體在暗室中作針孔成像實驗，眼睛為觀察者位置，則屏上的像之形狀為下列何者？（不考慮大小）", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 1, "e": "針孔成像的像是「上下顛倒、左右相反」，相當於把原圖旋轉 180°。\nQ 的小尾巴原本在右下方，旋轉 180° 後跑到左上方，就是圖 (B)。\n★ 針孔成像＝旋轉 180°：上下、左右一起顛倒。", "h": [], "rep": false, "img": "s4-q74", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-75", "no": "75", "c": "k2", "src": "自修 p.155", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "住在嘉義北回歸線，身高為 160 cm 的小華，春分的正午發現自己的影長為 70 cm，而一旁的電線桿之影長為 245 cm，則此電線桿高度接近下列何者？", "o": ["4.8 m", "5.6 m", "6.4 m", "7.2 m"], "a": 1, "e": "太陽光是平行光，同一時刻物高和影長成正比。\n160÷70＝電線桿高÷245 → 電線桿高＝160×245÷70＝560 cm＝5.6 m。\n★ 太陽下：高度÷影長＝固定值。", "h": ["列出比例：身高÷影長＝電線桿高÷影長。", "注意答案的單位是公尺。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-76", "no": "76", "c": "k13", "src": "自修 p.156", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列生活中的一些現象，哪一項與光的直線傳播無關？", "o": ["一人以單眼目視，指揮另一同學排齊桌子", "民國 98 年 7 月 22 日發生本世紀最長的日全食", "下雨過後，天邊出現的彩虹", "穿衣能有蔽體之作用"], "a": 2, "e": "單眼目視排桌子、日全食、穿衣蔽體都和光的直線傳播有關。\n彩虹是陽光進入小水滴時折射、色散造成的，和直線傳播無關。\n★ 彩虹＝折射＋色散。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-77", "no": "77", "c": "k3", "src": "自修 p.156", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列何者可能是針孔成像的成像性質？", "o": ["倒立放大虛像", "正立縮小虛像", "倒立縮小實像", "正立放大實像"], "a": 2, "e": "針孔成像一定是光線真正交會在屏上 → 實像，而且一定倒立。\n大小看物距和像距：像距＜物距時就是縮小。所以可能是「倒立縮小實像」。\n★ 針孔成像不會有虛像，也不會是正立的。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-78", "no": "78", "c": "k3", "src": "自修 p.156", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "針孔成像實驗，分別操作下列何者（都維持針孔在燭火與紙屏之間）可以使成像長度變大？(甲)燭火移離針孔；(乙)燭火移近針孔；(丙)紙屏移近針孔；(丁)針孔移離紙屏。", "o": ["(甲)(乙)", "(丙)(丁)", "(甲)(丙)", "(乙)(丁)"], "a": 3, "e": "像長：物長＝像距：物距。要讓像變大，就要讓像距變大或物距變小。\n乙：燭火移近針孔 → 物距變小 → 像變大。\n丁：針孔移離紙屏 → 像距變大 → 像變大。\n★ 像要大：物近孔、屏遠孔。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-79", "no": "79", "c": "k2", "src": "自修 p.156", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "在暗室中點一燭火，將棒球置於燭火與白色牆壁之間作影子實驗，分別操作下列何者（都維持棒球在燭火與白牆之間）可以使影子的面積變小？(甲)棒球移近燭火；(乙)棒球移近白牆；(丙)燭火移離棒球；(丁)燭火向白牆移近。", "o": ["(甲)(乙)", "(乙)(丙)", "(丙)(丁)", "(甲)(丙)"], "a": 1, "e": "點光源造成的影子：棒球愈靠近牆（離光源愈遠），影子愈小。\n乙：棒球移近白牆 → 影子變小；丙：燭火移離棒球 → 影子變小。\n甲、丁都是讓棒球和燭火靠近，影子反而變大。\n★ 障礙物離光源愈遠、離牆愈近，影子愈小。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-80", "no": "80", "c": "k3", "src": "自修 p.156", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "如右圖，針孔成像實驗，燭火距屏 36 cm，火焰長 4 cm，針孔距屏 12 cm，則屏上火焰的長度為多少 cm？", "o": ["2", "4", "6", "8"], "a": 0, "e": "燭火距屏 36 cm、針孔距屏 12 cm → 物距＝36－12＝24 cm，像距＝12 cm。\n像長＝4 × 12÷24＝2 cm。\n★ 像長：物長＝像距：物距。", "h": ["先算出燭火到針孔的距離（物距）。", "像長＝物長 × 像距 ÷ 物距。"], "rep": false, "img": "s4-q80", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-81", "no": "81", "c": "k3", "src": "自修 p.156", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "承上題，下列操作，何者可使屏上火焰像長調長為 4 cm？", "o": ["燭火向左移 12 cm", "針孔向左移 6 cm", "屏向右移 18 cm", "燭火向右移 6 cm"], "a": 1, "e": "要讓像長＝物長＝4 cm，必須物距＝像距。\n針孔向左移 6 cm：物距＝24－6＝18 cm，像距＝12＋6＝18 cm，相等 → 像長 4 cm。\n其他選項：燭火左移 12 → 36：12；屏右移 18 → 24：30；燭火右移 6 → 18：12，都不相等。\n★ 像和物一樣大：物距＝像距。", "h": ["像長等於物長時，物距和像距有什麼關係？", "逐一算出每個選項移動後的物距和像距。"], "rep": false, "img": "s4-q81", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-82", "no": "82", "c": "k3", "src": "自修 p.156", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "以 PQR 字形發光體在暗室中作針孔成像實驗，右圖中眼睛為觀察者位置，由觀察者位置看物，由左而右為 PQR，則屏上的像，由左而右形狀為下列何者？（不考慮大小）", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 2, "e": "針孔成像的像相當於原圖旋轉 180°（上下顛倒、左右相反）。\n「PQR」旋轉 180° 後，順序變成 R、Q、P，而且每個字母都倒過來，就是圖 (C)。\n★ 針孔成像＝旋轉 180°。", "h": [], "rep": false, "img": "s4-q82", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-83", "no": "83", "c": "k6", "src": "自修 p.172", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "平面鏡成像性質，下列何者正確？", "o": ["正立等大實像", "正立等大虛像", "倒立縮小虛像", "倒立放大實像"], "a": 1, "e": "平面鏡成像：正立、等大、虛像，像距＝物距。\n光沒有真的到鏡子後面，所以是虛像，無法在紙屏上看到。\n★ 平面鏡：正立等大虛像。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-84", "no": "84", "c": "k6", "src": "自修 p.172", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "平面鏡成像是利用光的哪一項性質？", "o": ["反射", "繞射", "折射", "直進"], "a": 0, "e": "平面鏡是利用光的反射來成像。\n★ 鏡子（平面鏡、凹面鏡、凸面鏡）→ 反射；透鏡 → 折射。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-85", "no": "85", "c": "k5", "src": "自修 p.172", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列何者不屬於光的反射？", "o": ["單向反射", "鏡面反射", "漫射", "折射"], "a": 3, "e": "單向反射（鏡面反射）和漫射都是光的反射。\n折射是光進入另一介質後方向改變，不是反射。\n★ 反射分為：鏡面反射（單向反射）、漫射。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-86", "no": "86", "c": "k6", "src": "自修 p.172", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "身高為 160 公分的小孟站立於大平面鏡前 1 公尺、2 公尺、3 公尺處，成像像高大小分別為 H1、H2、H3 公分，則下列何者正確？", "o": ["H1 > H2 > H3", "H1 < H2 < H3", "H1 = H2 = H3 < 160 公分", "H1 = H2 = H3 = 160 公分"], "a": 3, "e": "平面鏡成像是等大的像，像高永遠等於物高 160 公分，和離鏡子遠近無關。\n（走遠時覺得像變小，是因為眼睛看遠處物體的視角變小。）\n★ 平面鏡：像的大小＝物的大小。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-87", "no": "87", "c": "k5", "src": "自修 p.172", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "一束紅光雷射與平面鏡鏡面成 30° 入射，下列何者錯誤？", "o": ["入射角＝30°", "反射光與鏡面成 30°", "法線與入射光成 60°", "反射光與法線成 60°"], "a": 0, "e": "光線與鏡面成 30°，入射角是光線與「法線」的夾角＝90°－30°＝60°，所以 (A)「入射角＝30°」錯誤。\n反射光與鏡面也成 30°，與法線成 60°；法線與入射光成 60°。\n★ 入射角＝90°－光線與鏡面的夾角。", "h": ["入射角是和法線的夾角，不是和鏡面的夾角。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-88", "no": "88", "c": "k6", "src": "自修 p.172", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "一原子筆斜放平面鏡前，如右圖，筆尖距平面鏡 12 cm，成像於 P 點，筆蓋距平面鏡 16 cm，成像於 Q 點，則下列何者正確？", "o": ["P 點距平面鏡 12 cm", "P 點距平面鏡 16 cm", "Q 點距平面鏡 12 cm", "Q 點距平面鏡 14 cm"], "a": 0, "e": "平面鏡成像：像距＝物距，每一點都對稱於鏡面。\n筆尖距鏡 12 cm → 像 P 點也距鏡 12 cm；筆蓋距鏡 16 cm → Q 點也距鏡 16 cm。\n★ 像距＝物距（每一點都一樣）。", "h": [], "rep": false, "img": "s4-q88", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-89", "no": "89", "c": "k6", "src": "自修 p.172", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "如右圖，一發光字體 G 置於平面鏡前，觀察者在圖左側看到字體為 G，同時看平面鏡中的成像應為下列何者？", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 1, "e": "發光字 G 在觀察者和平面鏡之間，鏡中的像和字對稱於鏡面。\n因為鏡子正對著觀察者，像的每一點左右位置不變，所以從觀察者的方向看，鏡中看到的還是「G」，即圖 (B)。\n★ 鏡子正對你時：物體上的每一點在鏡中「左右位置不變、只有前後相反」。", "h": [], "rep": false, "img": "s4-q89", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-90", "no": "90", "c": "k6", "src": "自修 p.172", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "不透明紙上有一數字 9132，面向平面鏡成像所看到的像為下列何者？", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 2, "e": "數字面向平面鏡，鏡中的像是左右相反的鏡像：順序變成 2、3、1、9，而且每個數字都左右翻轉，就是圖 (C)。\n★ 鏡中的文字：整串左右相反（順序顛倒、每字翻轉）。", "h": [], "rep": false, "img": "s4-q90", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-91", "no": "91", "c": "k8", "src": "自修 p.185", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "一束雷射光斜向由空氣往水面照，下列敘述何者正確？", "o": ["全部光能量進入水中，方向不變", "全部光能量進入水中，方向偏離法線", "部分光能量反射，部分光能量折射，折射方向偏離法線", "部分光能量反射，部分光能量折射，折射方向偏向法線"], "a": 3, "e": "光從空氣斜射到水面時，一部分反射、一部分折射進入水中。\n進入水中速率變慢，折射光會偏向法線。\n★ 斜射到界面：反射＋折射同時發生；快 → 慢偏向法線。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-92", "no": "92", "c": "k8", "src": "自修 p.185", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "一束紅光雷射由空氣入射水面，進入水中之光線，下列敘述何者正確？", "o": ["方向一定改變", "頻率一定不變", "波長變長", "週期變小"], "a": 1, "e": "光從空氣進入水中：頻率由光源決定，不會改變。\n速率變慢，波長＝v÷f 也變短；週期＝1÷f 不變。\n如果垂直入射，方向就不會改變，所以 (A) 不一定。\n★ 光進入不同介質：頻率不變，速度和波長改變。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-93", "no": "93", "c": "k8", "src": "自修 p.185", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "一束光線斜向由空氣入射玻璃，其入射角與折射角大小的關係，下列何者正確？", "o": ["折射角＜入射角", "折射角＝入射角", "折射角≥入射角", "折射角＞入射角"], "a": 0, "e": "光從空氣（快）斜射入玻璃（慢），會偏向法線，所以折射角小於入射角。\n★ 快 → 慢：折射角＜入射角。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-94", "no": "94", "c": "k8", "src": "自修 p.185", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "光由一介質斜向進入另一介質，造成前進方向改變之原因，是因下列何者改變之故？", "o": ["強度", "速率", "頻率", "週期"], "a": 1, "e": "光進入不同介質時傳播速率改變，所以方向偏折。頻率、週期不變。\n★ 折射的原因是光速改變。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-95", "no": "95", "c": "k4", "src": "自修 p.185", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "光在真空中速率為 3 × 10⁵ 公里／秒，在水中速率為 2.25 × 10⁵ 公里／秒，若以 c 代表光在真空中之速率，則光在水中之速率為下列何者？", "o": ["2/3 c", "3/2 c", "3/4 c", "4/3 c"], "a": 2, "e": "光在水中的速率÷光在真空中的速率＝2.25×10⁵ ÷ 3×10⁵＝0.75＝3/4。\n所以光在水中速率＝3/4 c。\n★ 光在水中約 3/4 c、玻璃約 2/3 c。", "h": ["把水中的光速除以真空中的光速。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-96", "no": "96", "c": "k4", "src": "自修 p.185", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "光在下列介質之速度大小順序，何者正確？(甲)空氣；(乙)玻璃；(丙)鑽石；(丁)水。", "o": ["(甲)＞(乙)＞(丙)＞(丁)", "(甲)＞(丁)＞(丙)＞(乙)", "(甲)＞(丁)＞(乙)＞(丙)", "(丁)＞(甲)＞(丙)＞(乙)"], "a": 2, "e": "介質愈密，光愈慢：空氣＞水＞玻璃＞鑽石。\n所以甲（空氣）＞丁（水）＞乙（玻璃）＞丙（鑽石）。\n★ 光速：真空＞空氣＞水＞玻璃＞鑽石。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-97", "no": "97", "c": "k9", "src": "自修 p.185", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "一枚拾元硬幣置於一深度為 12 公分空杯底正中央處，人眼位於杯口正上方往杯底看，同時加水入杯子，則加水高度至下列何者時，所看到的硬幣距杯口最近？", "o": ["3 公分", "6 公分", "9 公分", "12 公分"], "a": 3, "e": "硬幣反射的光從水中射入空氣會偏折，看起來位置變淺（被抬高）。\n水加得愈多，抬高的距離愈大，看起來離杯口愈近。所以加到 12 公分（裝滿）時最近。\n★ 水愈深，物體被「抬高」得愈多。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-98", "no": "98", "c": "k9", "src": "自修 p.185", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "學校游泳池正常水位高度為 120 cm，上游泳課時嘉良老師站在池邊往水底觀察水況，同時向學生講解水中安全注意事項，則嘉良老師所看到池底的深度可能為下列何者？", "o": ["90 cm", "120 cm", "150 cm", "180 cm"], "a": 0, "e": "從空氣中看水底，光從水進入空氣偏離法線，看到的池底比實際淺。\n實際水深 120 cm，看起來會比 120 cm 淺，所以可能是 90 cm。\n★ 從岸上看水底 → 看起來比較淺。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-99", "no": "99", "c": "k9", "src": "自修 p.185", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "夕陽快西沉時，看到太陽在遠處海面上方約 1 公尺高處，則實際太陽的位置與看到的位置比較，下列何者正確？", "o": ["實際位置較低", "實際位置較高", "看到的位置就是實際的位置", "無法判斷"], "a": 0, "e": "太陽光從太空進入大氣層，空氣愈靠近地面愈密，光會向下彎折。\n我們沿著進入眼睛的光線方向看，看到的太陽比實際位置高，所以實際位置較低。\n★ 大氣折射：看到的天體比實際高（日落時太陽其實已經在地平線下）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-100", "no": "100", "c": "k9", "src": "自修 p.186", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "海面上方 2 公尺處有一隻海鳥，水面下方 1 公尺處有一條海魚，由鳥看魚及魚看鳥之距離水面的情形，下列何者正確？", "o": ["鳥看魚，距水面大於 1 公尺；魚看鳥，距水面小於 2 公尺", "鳥看魚，距水面小於 1 公尺；魚看鳥，距水面大於 2 公尺", "鳥看魚，距水面小於 1 公尺；魚看鳥，距水面小於 2 公尺", "鳥看魚，距水面大於 1 公尺；魚看鳥，距水面大於 2 公尺"], "a": 1, "e": "鳥看魚：光從水射入空氣，看到的魚比實際淺 → 距水面小於 1 公尺。\n魚看鳥：光從空氣射入水中，看到的鳥比實際高 → 距水面大於 2 公尺。\n★ 空氣看水中：變淺；水中看空氣：變高。", "h": [], "rep": false, "img": "s4-q100", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-101", "no": "101", "c": "k9", "src": "自修 p.186", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "由空氣中看天空中的恆星、行星等天體，所看到的高度位置與實際位置有些出入，是因為光線的哪一種現象所造成的？", "o": ["直進", "漫反射", "鏡面反射", "折射"], "a": 3, "e": "大氣層愈接近地面愈密，星光穿過大氣時會折射偏折，所以看到的位置和實際位置不同。\n★ 天體位置偏移、星星閃爍 → 大氣折射。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-102", "no": "102", "c": "k9", "src": "自修 p.186", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "筷子一部分在空氣中，一部分在水中時，我們在空氣中所看到的情形為下列何者？", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 3, "e": "筷子水中部分反射的光從水進入空氣，會偏離法線，看起來比實際位置淺（被抬高）。\n所以水中的筷子看起來在水面處「向上折」，比較平、不那麼陡，就是圖 (D)。\n★ 斜插水中的筷子：水中部分看起來往上翹。", "h": [], "rep": false, "img": "s4-q102", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-103", "no": "103", "c": "k8", "src": "自修 p.186", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "魚由水裡看天空中飛行的海鳥，下列何者為合理的光線路徑方向？", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 0, "e": "魚看見鳥，是鳥反射的光進入魚的眼睛 → 光線方向由鳥射向魚。\n光從空氣（快）進入水中（慢），會偏向法線，水中的光線比空氣中的更陡。\n圖 (A) 箭頭由鳥指向魚，而且進入水中後偏向法線。\n★ 先判斷光從哪裡來（被看的物體 → 眼睛），再判斷偏向或偏離法線。", "h": [], "rep": false, "img": "s4-q103", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-104", "no": "104", "c": "k8", "src": "自修 p.186", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "空中飛行的海鳥，看見水中的魚，下列何者為合理的光線路徑方向？", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 1, "e": "鳥看見魚，是魚的光進入鳥的眼睛 → 光線方向由魚射向鳥。\n光從水（慢）進入空氣（快），會偏離法線，空氣中的光線比水中的更斜。\n圖 (B) 箭頭由魚指向鳥，出水後偏離法線。\n★ 慢 → 快：偏離法線。", "h": [], "rep": false, "img": "s4-q104", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-105", "no": "105", "c": "k8", "src": "自修 p.186", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "一束光線垂直一塊 30°－60°－90° 的玻璃材質三稜鏡入射，如右圖，則哪一條光線為其合理的折射路徑？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "光垂直射入三稜鏡的第一個面，入射角 0°，方向不變。\n到達斜面時由玻璃（慢）射入空氣（快），入射角約 30°，會偏離法線射出。\n圖中偏離法線射出的折射光是丙。\n★ 玻璃 → 空氣：偏離法線。", "h": [], "rep": false, "img": "s4-q105", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-106", "no": "106", "c": "k8", "src": "自修 p.187", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "一束光在 Ⅰ、Ⅱ 兩介質間之傳播路徑如右圖，傳播速率 PO 為甲，OR 為乙，OQ 為丙，則三者大小順序為下列何者？", "o": ["甲＝乙＞丙", "甲＝乙＜丙", "丙＞甲＞乙", "甲＞乙＞丙"], "a": 1, "e": "PO（入射）和 OR（反射）都在介質 Ⅰ 中，同一介質光速相同 → 甲＝乙。\n圖中入射角 30°、折射角 50°，折射角比入射角大 → 光偏離法線 → 介質 Ⅱ 比較快。\n所以甲＝乙＜丙。\n★ 折射角＞入射角 → 進入較快的介質。", "h": [], "rep": false, "img": "s4-q106", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-107", "no": "107", "c": "k8", "src": "自修 p.187", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "承上題，各種角度的敘述，下列何者正確？", "o": ["入射角為 60°", "反射角為 60°", "∠ROQ = 100°", "折射角為 40°"], "a": 2, "e": "入射角＝PO 與法線的夾角＝30°，反射角也＝30°，折射角＝50°，所以 (A)(B)(D) 錯誤。\n∠ROQ＝180°－反射角－折射角＝180°－30°－50°＝100°，(C) 正確。\n★ 角度一律看和「法線」的夾角。", "h": ["從圖上讀出入射角和折射角（和法線的夾角）。", "反射線與折射線夾角＝180°－反射角－折射角。"], "rep": false, "img": "s4-q107", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-108", "no": "108", "c": "k9", "src": "自修 p.187", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "如右圖，一支吸管置於一平行厚玻璃塊後方偏右側，吸管上下方沒被厚玻璃塊擋住，而人從厚玻璃塊前方偏左處看，所看到的情形會是下列何者？", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 0, "e": "吸管被玻璃擋住的部分，光要先穿過厚玻璃再進入眼睛，在玻璃中偏向法線，出來後的光線會往側邊平移。\n人從左前方看，沿著進入眼睛的光線往回看，玻璃後的那一段看起來向「右」平移（遠離觀察者的方向），就是圖 (A)。\n★ 斜著透過厚玻璃看東西：看到的位置會平移，方向不變。", "h": [], "rep": false, "img": "s4-q108", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-109", "no": "109", "c": "k8", "src": "自修 p.187", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "光由空氣與厚玻璃片成 30° 射向玻璃，下列敘述何者正確？", "o": ["折射角大於入射角", "同時有反射和折射發生", "光速變快", "波長變長"], "a": 1, "e": "光斜射到玻璃時，一部分反射、一部分折射，(B) 正確。\n進入玻璃（較慢）偏向法線，折射角小於入射角；光速變慢、波長變短。\n★ 斜射：反射和折射同時發生。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-110", "no": "110", "c": "k8", "src": "自修 p.187", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "一束雷射紅光與水面成 90°，由空氣中入射水中，則下列敘述何者錯誤？", "o": ["折射角＝90°", "光速變慢", "仍為紅光", "波長變短"], "a": 0, "e": "光與水面成 90°，就是垂直入射，入射角＝0°，折射角也＝0°，方向不變，所以「折射角＝90°」錯誤。\n進入水中光速變慢、波長變短，顏色（頻率）不變，仍是紅光。\n★ 垂直入射：方向不變，但速度還是會變。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-111", "no": "111", "c": "k8", "src": "自修 p.187", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "水球形氣泡形成上浮中，有一束光線由水中射入氣泡中，右圖中所標示光線在同一平面上，且此平面通過球形氣泡的球心 (O)，則下列何者最可能為光的行進路徑？", "o": ["acde", "acdf", "bcde", "bcdf"], "a": 0, "e": "光從水（慢）進入空氣泡（快）時，在 c 點會偏離法線（法線是通過球心的半徑）。\n從 a 射入，折射後偏離法線，才會走 cd 這條路徑。\n光從 d 點由空氣回到水中會偏向法線（向半徑方向靠近），往 e 射出。\n所以路徑是 acde。\n★ 圓形界面的法線＝連到圓心的半徑。", "h": [], "rep": false, "img": "s4-q111", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-112", "no": "112", "c": "k9", "src": "自修 p.187", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "右圖甲物在一厚片玻璃後方，其反射光線經玻璃折射後之路徑如右圖所示，進入戊處的人眼，則戊處所看到甲的像會在何處？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "人眼在戊處，看到的甲在「進入眼睛的光線往回延長」的方向上。\n把玻璃下方那段光線往上延長到甲所在的高度，會落在丙的位置。\n★ 看到的位置＝進入眼睛光線的反向延長線。", "h": [], "rep": false, "img": "s4-q112", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-113", "no": "113", "c": "k8", "src": "翰林 A卷 第7回 第 18 題", "st": "考卷", "pk": "ha-7", "pname": "翰林 A卷・第7回（4-1～4-3）", "pord": 1, "ctx": "", "fig": "", "q": "固定以 45° 入射角將雷射光入射甲、乙、丙三種介質，結果折射線與界面夾角：甲為 20°、乙為 30°、丙為 55°，則雷射光在三介質中之光速大小順序為何？", "o": ["丙＞乙＞甲", "乙＞甲＞丙", "甲＞乙＞丙", "丙＞甲＞乙"], "a": 2, "e": "入射角 45°，折射角＝90°－折射線與界面夾角：甲 70°、乙 60°、丙 35°。\n折射角愈大（離法線愈遠），光在該介質中愈快 → 甲＞乙＞丙。\n★ 題目給的是「與界面的夾角」，要先換成與法線的夾角。", "h": ["先把與界面的夾角換成折射角（90° 減去它）。", "折射角愈大，光速愈快。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-114", "no": "114", "c": "k8", "src": "自修 p.188", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "一束光線由空氣中與水面成 30° 入射水中，折射角為 41°，則反射線與折射線夾角為多少度？", "o": ["71°", "79°", "101°", "109°"], "a": 1, "e": "光與水面成 30° → 入射角＝60°，反射角＝60°。\n反射線與折射線夾角＝180°－60°－41°＝79°。\n★ 夾角＝180°－反射角－折射角。", "h": ["先算出入射角（90° 減去與水面的夾角）。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-115", "no": "115", "c": "k8", "src": "自修 p.188", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "一束紅色光由空氣中垂直水面入射水中，下列敘述何者正確？", "o": ["速率變快，方向不變", "速率不變，方向不變", "頻率不變，方向改變", "速率變慢，方向不變"], "a": 3, "e": "垂直入射時入射角 0°，光不偏折，方向不變。\n但進入水中速率仍然變慢。\n★ 垂直入射：方向不變、速率改變。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-116", "no": "116", "c": "k5", "src": "翰林 A卷 第7回 素養題 7", "st": "考卷", "pk": "ha-7", "pname": "翰林 A卷・第7回（4-1～4-3）", "pord": 1, "ctx": "A、B 兩平面鏡夾角為 125°，入射光線與 A 平面鏡的夾角為 30°，如右圖所示。", "fig": "", "q": "如果想要 A 平面鏡的反射光，不會射入 B 平面鏡，則以 A、B 平面鏡交點為轉軸，至少必須將 B 平面鏡如何轉動？", "o": ["逆時針旋轉 15°", "逆時針旋轉 25°", "順時針旋轉 15°", "順時針旋轉 25°"], "a": 1, "e": "A 鏡的反射光與 A 鏡也成 30°，射向 B 鏡；A、B 夾角 125°，要讓反射光剛好不射到 B 鏡，反射光要和 B 鏡平行或從外側通過。\n反射光與 A 鏡成 30°，B 鏡要轉到和反射光平行時，A、B 的夾角要變成 180°－30°＝150°。\n從 125° 變成 150°，B 鏡至少要逆時針轉 25°。\n★ 想讓光不射到鏡子 → 鏡子至少要轉到和光線平行。", "h": ["A 鏡反射光與鏡面的夾角是多少？", "B 鏡轉到和反射光平行時，A、B 夾角是幾度？"], "rep": true, "img": "s4-q116", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-117", "no": "117", "c": "k1", "src": "翰林 A卷 第7回 活用題 2", "st": "考卷", "pk": "ha-7", "pname": "翰林 A卷・第7回（4-1～4-3）", "pord": 1, "ctx": "", "fig": "", "q": "如圖(二)，以雷射光照射在純水中無法看見雷射光束，如圖(四)，廖老師在水中滴入幾滴牛奶攪拌後再照射雷射光便可以清楚的見到雪射光束。則廖老師是利用光的何種特性讓光點看得見？", "o": ["直線傳播", "反射", "折射", "雷射光能量集中"], "a": 1, "e": "純水很均勻，雷射光沒有碰到東西，光不會進入我們的眼睛，所以看不到光束。\n滴入牛奶後，水中有很多小顆粒，雷射光照到顆粒時向四面八方反射（漫射），部分光進入眼睛，就看得見光束了。\n★ 看見光束：要有微粒把光反射到眼睛。", "h": [], "rep": true, "img": "s4-q117", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-118", "no": "118", "c": "k6", "src": "翰林 A卷 第7回 活用題 3", "st": "考卷", "pk": "ha-7", "pname": "翰林 A卷・第7回（4-1～4-3）", "pord": 1, "ctx": "", "fig": "", "q": "做視力檢查時，眼睛與視力表的標準距離應為 5 公尺。某眼鏡行由於空間太小，所以使用一平面鏡反射視力表，若視力表與平面鏡的距離縮短為 3 公尺，則受測試者的座位應該設在距平面鏡多少公尺處？", "o": ["1 公尺", "2 公尺", "2.5 公尺", "3 公尺"], "a": 1, "e": "視力表的像在鏡後 3 公尺。受測者到「像」的距離要是 5 公尺。\n受測者到鏡子的距離＝5－3＝2 公尺。\n★ 用鏡子量距離：人到鏡＋鏡到像＝標準距離。", "h": ["視力表的像在鏡子後方幾公尺？", "人到像的距離要等於 5 公尺。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-119", "no": "119", "c": "k6", "src": "翰林 A卷 第7回 活用題 5", "st": "考卷", "pk": "ha-7", "pname": "翰林 A卷・第7回（4-1～4-3）", "pord": 1, "ctx": "", "fig": "", "q": "明玲坐在平面鏡前，從平面鏡看到身後牆壁所掛時鐘的成像，如右圖所示，則此時正確的時刻是幾點幾分？", "o": ["1 點 20 分", "7 點 40 分", "10 點 40 分", "11 點 20 分"], "a": 2, "e": "鏡中的時鐘是左右相反的。鏡中時針在 1 和 2 之間、分針在 4（20 分）。\n左右翻回來：分針在 8 → 40 分；時針在 10 和 11 之間 → 10 點 40 分。\n也可以用 12：00 減去鏡中時間：12:00－1:20＝10:40。\n★ 鏡中的時鐘：實際時間＝12:00－鏡中時間。", "h": ["鏡中的鐘是左右相反，可以把圖翻過來看。", "或用 12:00 減去鏡中看到的時間。"], "rep": false, "img": "s4-q119", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-120", "no": "120", "c": "k5", "src": "翰林 A卷 第7回 活用題 6", "st": "考卷", "pk": "ha-7", "pname": "翰林 A卷・第7回（4-1～4-3）", "pord": 1, "ctx": "M、N 兩平面鏡的鏡面夾角為 80°，光線 X 與 M 鏡面的夾角為 50°，射向 M 鏡後再反射到 N 鏡。", "fig": "M、N 兩相交平面鏡，夾角標記為 80°，光線 X 入射與 M 夾角 50°", "q": "M、N 兩平面鏡放置如右圖，M 和 N 夾角 80°，今一條光線 X 和 M 夾角 50° 射向 M，則 X 經 M、N 兩平面鏡反射後，在 N 平面鏡的反射角為何？", "o": ["10°", "20°", "30°", "40°"], "a": 3, "e": "X 與 M 鏡面夾角 50°，反射光與 M 鏡面也成 50°。\n反射光、M 鏡、N 鏡圍成三角形：180°－80°－50°＝50°，即反射光與 N 鏡面夾角 50°。\n所以在 N 鏡的入射角＝90°－50°＝40°，反射角也是 40°。\n★ 兩面鏡子的題目：利用三角形內角和 180°。", "h": ["反射光與 M 鏡面的夾角也是 50°。", "三角形內角和 180°，求出反射光與 N 鏡面的夾角。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-121", "no": "121", "c": "k8", "src": "翰林 C卷 第7回 素養題 4", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "光由空氣射向半圓形的玻璃磚時，下列哪一個是其行進路線圖？", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 3, "e": "光從空氣射到半圓玻璃磚的平面上時，會反射也會折射，折射光偏向法線（光變慢）。\n進入玻璃後，若光線沿半徑方向射到圓弧面，就是垂直射到弧面，不會再偏折。\n四個圖中只有 (D) 的反射、折射方向都正確。\n★ 沿半徑方向射到圓弧＝垂直入射，不偏折。", "h": [], "rep": true, "img": "s4-q121", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-122", "no": "122", "c": "k10", "src": "翰林 B卷 第8回 第 1 題", "st": "考卷", "pk": "hb-8", "pname": "翰林 B卷・第8回（4-4～4-5）", "pord": 4, "ctx": "", "fig": "", "q": "利用焦距為 8 cm 之凸透鏡，會聚太陽光於一張紙上，則凸透鏡與紙張距離多少時，紙張最易燃燒？", "o": ["4 cm", "8 cm", "16 cm", "16 cm 以上"], "a": 1, "e": "凸透鏡把平行的太陽光會聚在焦點上，那裡光最集中、溫度最高。\n焦距 8 cm → 紙放在距透鏡 8 cm 處最容易燃燒。\n★ 聚光點＝焦點。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-123", "no": "123", "c": "k11", "src": "翰林 B卷 第8回 第 2 題", "st": "考卷", "pk": "hb-8", "pname": "翰林 B卷・第8回（4-4～4-5）", "pord": 4, "ctx": "", "fig": "", "q": "關於平面鏡、凹面鏡、凸面鏡、凸透鏡可能成像的敘述，下列何者錯誤？", "o": ["平面鏡——正立等大虛像", "凹面鏡——正立放大虛像", "凸面鏡——正立縮小虛像", "凸透鏡——正立縮小虛像"], "a": 3, "e": "平面鏡：正立等大虛像；凹面鏡近看：正立放大虛像；凸面鏡：正立縮小虛像。\n凸透鏡的虛像只有「正立放大虛像」（物體在焦點內），不會有正立縮小虛像，所以 (D) 錯誤。\n★ 正立縮小虛像只有凸面鏡和凹透鏡。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-124", "no": "124", "c": "k11", "src": "翰林 B卷 第8回 第 3 題", "st": "考卷", "pk": "hb-8", "pname": "翰林 B卷・第8回（4-4～4-5）", "pord": 4, "ctx": "", "fig": "", "q": "凸透鏡前有一朵花，其位置如右圖所示，則經過透鏡折射後會形成下列何種像？", "o": ["倒立縮小花朵", "倒立放大花朵", "正立放大花朵", "倒立等大花朵"], "a": 1, "e": "圖中花在凸透鏡的 F 和 2F 之間（f～2f），會在鏡後 2F 外成倒立放大實像。\n★ f＜物距＜2f → 倒立放大實像。", "h": [], "rep": false, "img": "s4-q124", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-125", "no": "125", "c": "k11", "src": "翰林 B卷 第8回 第 4 題", "st": "考卷", "pk": "hb-8", "pname": "翰林 B卷・第8回（4-4～4-5）", "pord": 4, "ctx": "", "fig": "", "q": "物體置於一凸透鏡前，所成之正立放大虛像情形如右圖所示，則物體頂點所反射出之光線 PO 經透鏡折射後之路徑，最接近下列何者？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "正立放大虛像 P' 是折射光的「反向延長線」交出來的。\n所以 PQ 折射後，往回延長必須通過虛像頂點 P'。\n在圖中，只有丁這條光線往回延長會經過 P'。\n★ 虛像：折射光往回延長的交點。", "h": [], "rep": false, "img": "s4-q125", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-126", "no": "126", "c": "k11", "src": "翰林 B卷 第8回 第 5 題", "st": "考卷", "pk": "hb-8", "pname": "翰林 B卷・第8回（4-4～4-5）", "pord": 4, "ctx": "", "fig": "", "q": "關於判別實像、虛像的依據，下列何者正確？", "o": ["平面鏡所成的是虛像，透鏡所成的是實像", "由光的反向延長線交會而成的是實像，折射而成的是虛像", "實像能透過紙屏看到，虛像則無法", "虛像是放大實物，實像必定是縮小的"], "a": 2, "e": "實像是光線真正會聚而成，可以用紙屏接到；虛像是延長線交會，紙屏接不到。\n平面鏡是虛像沒錯，但透鏡也可能成虛像；反射、折射都可能成實像或虛像；虛像不一定放大，實像不一定縮小。\n★ 判斷實像、虛像：能不能用紙屏接到。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-127", "no": "127", "c": "k11", "src": "翰林 B卷 第8回 第 17 題", "st": "考卷", "pk": "hb-8", "pname": "翰林 B卷・第8回（4-4～4-5）", "pord": 4, "ctx": "", "fig": "", "q": "一物體置於透鏡眼鏡鏡片的一倍焦距與兩倍焦距之間，則生成的像為何？", "o": ["倒立縮小實像", "倒立放大實像", "正立放大虛像", "正立縮小虛像"], "a": 1, "e": "遠視眼鏡是凸透鏡。物體在凸透鏡的一倍焦距和兩倍焦距之間，成倒立放大實像。\n★ 遠視眼鏡、放大鏡＝凸透鏡。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-128", "no": "128", "c": "k7", "src": "翰林 C卷 第7回 題組 1", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "汽車的後視鏡可看到後方大範圍的景物，請問這是使用下列哪一種面鏡？", "o": ["凸面鏡", "凹面鏡", "平面鏡", "哈哈鏡"], "a": 0, "e": "後照鏡要看到大範圍的景物，用凸面鏡，成正立縮小虛像。\n★ 凸面鏡：視野大。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-129", "no": "129", "c": "k6", "src": "翰林 C卷 第7回 題組 2", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "在萬花筒中可以看到五彩繽紛的圖案，是利用物理學中光的何種原理？", "o": ["折射", "反射", "直進", "干涉"], "a": 1, "e": "萬花筒裡面是幾面互成角度的平面鏡，光在鏡子間多次反射，形成許多對稱的像。\n★ 萬花筒＝平面鏡多次反射。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-130", "no": "130", "c": "k7", "src": "翰林 C卷 第7回 素養題 1", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "手電筒的光源通常是裝在何種光學鏡片的焦點上以增加亮度？", "o": ["凹面鏡", "凸面鏡", "凹透鏡", "平面鏡"], "a": 0, "e": "手電筒、探照燈的燈泡放在凹面鏡的焦點上，光反射後變成平行光射出，照得又亮又遠。\n★ 光源在凹面鏡焦點 → 反射成平行光。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-131", "no": "131", "c": "k2", "src": "翰林 C卷 第7回 素養題 2", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "關於手影遊戲的敘述，下列何者錯誤？", "o": ["手愈貼近光源，手影愈大", "手影遊戲所運用的科學原理和日晷相同", "只要將手愈靠近紙幕，手影一定會愈清晰", "玩手影遊戲時，手必須放在光源和紙幕的中間"], "a": 2, "e": "手影是光的直進造成的影子，和日晷原理相同；手要在光源和紙幕之間。\n手愈靠近光源，影子愈大。\n手靠近紙幕影子會變小、邊緣較清楚，但光源很大時仍有半影，不是「一定」愈清晰，所以 (C) 錯誤。\n★ 有「一定」的選項要特別小心。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-132", "no": "132", "c": "k6", "src": "翰林 C卷 第7回 素養題 3", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "在眼鏡店裡，一面牆上掛著一平面鏡，對面的牆上則掛著一張視力測試表。測試表與平面鏡間的距離為 3.5 m，如右圖所示。則該顧客所看到測試表的像與她相距多少 m？", "o": ["1.0", "2.5", "3.5", "6.0"], "a": 3, "e": "測試表的像在鏡後 3.5 m。顧客距鏡子 2.5 m。\n顧客到像的距離＝2.5＋3.5＝6.0 m。\n★ 人到像的距離＝人到鏡＋鏡到像。", "h": ["測試表的像在鏡子後方幾公尺？", "把人到鏡子的距離加上去。"], "rep": false, "img": "s4-q132", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-133", "no": "133", "c": "k9", "src": "翰林 C卷 第7回 素養題 5", "st": "考卷", "pk": "hc-7", "pname": "翰林 C卷・第7回（4-1～4-3）", "pord": 5, "ctx": "", "fig": "", "q": "他良和同學騎腳踏車到公園玩，由於天氣大熱，同學建議跳到水池泡水，於是四、五個人便往水池跳，原本看起來很淺的水池，但跳入後才發現池水很深，試問其原因為何？", "o": ["光折射所造成的結果", "光反射所造成的結果", "光漫射所造成的結果", "光速變慢所造成的結果"], "a": 0, "e": "池底反射的光從水中進入空氣時偏離法線，看起來池底比實際淺。\n所以看起來淺的水池，跳下去才發現很深，這是光的折射造成的。\n★ 水看起來比實際淺 → 折射。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-134", "no": "134", "c": "k11", "src": "翰林 A卷 第8回 第 14 題", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（4-4～4-5）", "pord": 2, "ctx": "", "fig": "四個選項繪出不同剖面結構的透鏡示意圖", "q": "小明使用下列哪一面透鏡可以做出正立、倒立的像？", "o": ["雙凹透鏡", "雙凸透鏡", "平凹透鏡", "凸凹透鏡（中央薄邊緣厚）"], "a": 1, "e": "只有凸透鏡能同時成正立的像（虛像，物在焦點內）和倒立的像（實像，物在焦點外）。\n雙凸透鏡是凸透鏡（中央厚邊緣薄）；雙凹、平凹、凸凹透鏡都是凹透鏡，只能成正立縮小虛像。\n★ 正立、倒立都做得出來 → 凸透鏡。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-135", "no": "135", "c": "k14", "src": "翰林 A卷 第8回 第 15 題", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（4-4～4-5）", "pord": 2, "ctx": "", "fig": "", "q": "在日常生活中，能看到各種顏色的不透明物體，這是什麼原因呢？", "o": ["物體本身可以發出光線", "物體接受燈光或陽光照射，而反射所有光線", "物體受燈光或陽光照射，吸收部分色光，而反射物體顏色的光", "物體吸收所有色光"], "a": 2, "e": "不透明物體受光照射時，會吸收部分色光，只反射和自己顏色相同的色光，這些光進入眼睛，我們就看到它的顏色。\n★ 物體的顏色＝它反射的色光。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-136", "no": "136", "c": "k14", "src": "翰林 B卷 第8回 第 12 題", "st": "考卷", "pk": "hb-8", "pname": "翰林 B卷・第8回（4-4～4-5）", "pord": 4, "ctx": "", "fig": "", "q": "達華將電腦繪圖時，螢幕上會有一個色盤，可變換色彩的種類有 16 色、256 色、全彩等。則這些千變萬化的色彩，其實是幾種基本色光所調配出來的？", "o": ["3", "7", "2¹⁶", "2²⁵⁶"], "a": 0, "e": "螢幕上千變萬化的顏色，都是由紅、綠、藍三種色光（光的三原色）依不同比例混合出來的。\n★ 色光三原色：紅、綠、藍。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-137", "no": "137", "c": "k14", "src": "翰林 B卷 第8回 第 13 題", "st": "考卷", "pk": "hb-8", "pname": "翰林 B卷・第8回（4-4～4-5）", "pord": 4, "ctx": "", "fig": "", "q": "有一張正方形的彩色紙，上面塗有面積占 10% 的白色，20% 的綠色，30% 的紅色，40% 的藍色，以紅光照射後，呈現的紅色與黑色面積比為何？", "o": ["3：7", "2：3", "7：3", "3：2"], "a": 1, "e": "紅光照射：白色、紅色部分反射紅光 → 紅色面積＝10%＋30%＝40%。\n綠色、藍色部分吸收紅光 → 黑色面積＝20%＋40%＝60%。\n紅：黑＝40：60＝2：3。\n★ 單色光照射：白色和同色顯示該色，其他變黑。", "h": ["紅光下，哪些顏色會顯示紅色？哪些會變黑？", "把面積加起來再化簡成比。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-138", "no": "138", "c": "k14", "src": "翰林 B卷 第8回 第 14 題", "st": "考卷", "pk": "hb-8", "pname": "翰林 B卷・第8回（4-4～4-5）", "pord": 4, "ctx": "", "fig": "", "q": "若小鐘以黃光手電筒照射紅色的衣裳，依據色光混合圖（右圖），推論該衣服所呈現的顏色為何？", "o": ["紅色", "綠色", "黃色", "黑色"], "a": 0, "e": "黃光＝紅光＋綠光。紅色衣服只反射紅光、吸收綠光。\n所以黃光照射下，紅衣反射紅光，看起來仍是紅色。\n★ 黃光照紅色物體 → 紅色；黃光照綠色物體 → 綠色。", "h": [], "rep": true, "img": "s4-q138", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-139", "no": "139", "c": "k12", "src": "翰林 B卷 第8回 第 15 題", "st": "考卷", "pk": "hb-8", "pname": "翰林 B卷・第8回（4-4～4-5）", "pord": 4, "ctx": "", "fig": "", "q": "有關近視與遠視的敘述，下列何者正確？", "o": ["近視的人，眼睛水晶體的焦距過長", "近視的人，遠處的物體成像在視網膜前方，故模糊不清", "遠視的人，眼睛水晶體的焦距過短", "遠視的人，遠處的物體成像在視網膜後方，但很清晰"], "a": 1, "e": "近視：水晶體焦距太短，遠方物體成像在視網膜前方，看不清楚，(B) 正確。\n遠視：水晶體焦距太長，近處物體成像在視網膜後方，看近處模糊。\n★ 近視：焦距短、像在網膜前；遠視：焦距長、像在網膜後。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-140", "no": "140", "c": "k3", "src": "翰林 A卷 第9回 第 13 題", "st": "考卷", "pk": "ha-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 3, "ctx": "", "fig": "", "q": "針孔成像實驗時，若在針孔前放置一個會發光的 p 形燈管，如右圖，則光線通過針孔後，會在屏幕上形成什麼形狀的像？（由 p 向針孔方向看，不考慮大小）", "o": ["p", "q", "b", "d"], "a": 3, "e": "針孔成像是倒立實像：上下顛倒、左右相反，相當於旋轉 180°。\n由 p 往針孔看，p 旋轉 180° 後變成 d。\n★ 針孔成像＝旋轉 180°。", "h": [], "rep": true, "img": "s4-q140", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-141", "no": "141", "c": "k8", "src": "翰林 A卷 第9回 第 14 題", "st": "考卷", "pk": "ha-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 3, "ctx": "", "fig": "", "q": "一束光線 A，由甲介質射入乙介質，如右圖，則下列敘述何者錯誤？", "o": ["入射角 30°", "折射角 30°", "反射角 60°", "光在甲介質傳播速率比乙介質快"], "a": 0, "e": "光線 A 與界面的夾角是 30°，入射角是與法線的夾角＝90°－30°＝60°，所以 (A)「入射角 30°」錯誤。\n反射角＝60°；折射光與界面成 60° → 折射角＝30°。\n折射角＜入射角，光偏向法線，乙比較慢，所以光在甲中較快。\n★ 圖上標的角若是和界面的夾角，要先換算。", "h": ["圖中的 30° 是光線和「界面」的夾角。"], "rep": false, "img": "s4-q141", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-142", "no": "142", "c": "k14", "src": "翰林 A卷 第9回 第 15 題", "st": "考卷", "pk": "ha-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 3, "ctx": "", "fig": "", "q": "舞臺上投射的燈光及照設區域如右圖所示，下列敘述何者正確？", "o": ["白色的紙張放在丁處會變成黑色", "紅色紙張放在甲、丁處都為紅色", "藍色紙張在丙處為綠色", "白色紙張放在甲、丁處都為同樣顏色"], "a": 1, "e": "甲紅光、乙藍光、丙綠光，丁是三色光重疊處 → 白光。\n白紙在丁處是白色，在甲處是紅色，不會變黑，(A)(D) 錯。\n藍紙在丙（綠光）下吸收綠光 → 黑色，(C) 錯。\n紅紙在甲（紅光）和丁（白光）下都反射紅光 → 都是紅色，(B) 正確。\n★ 三色光重疊 → 白光。", "h": [], "rep": false, "img": "s4-q142", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-143", "no": "143", "c": "k11", "src": "翰林 A卷 第9回 第 16 題", "st": "考卷", "pk": "ha-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 3, "ctx": "", "fig": "", "q": "下列敘述何者錯誤？", "o": ["照相機所成的像為倒立縮小實像", "眼睛的水晶體相當於凸透鏡的作用", "使用放大鏡時，將物體放在客觀焦點內，可得放大虛像", "凸透鏡欲成一個放大的像，需將物體放在兩倍焦距外"], "a": 3, "e": "凸透鏡要成放大的像有兩種：物在 f～2f → 倒立放大實像；物在焦點內 → 正立放大虛像。\n物體放在兩倍焦距外，成的是倒立縮小實像，所以 (D) 錯誤。\n★ 物在 2f 外 → 縮小（照相機）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-144", "no": "144", "c": "k14", "src": "翰林 A卷 第9回 第 17 題", "st": "考卷", "pk": "ha-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 3, "ctx": "", "fig": "", "q": "如右圖，小姿貼近小孔看裡面的布娃娃，當燈光是白光時，看見娃娃上衣呈紅色，而裙子呈綠色，如果把燈泡換成綠光照射，則她所看到的肉況應該是下列何種情況？", "o": ["上衣呈紅色，裙子呈綠色", "上衣呈白色，裙子呈綠色", "上衣呈黑色，裙子呈綠色", "上衣呈綠色，裙子呈黑色"], "a": 2, "e": "白光下上衣紅色（只反射紅光）、裙子綠色（只反射綠光）。\n換成綠光照射：上衣吸收綠光 → 黑色；裙子反射綠光 → 綠色。\n★ 單色光照射：同色物體顯色，不同色物體變黑。", "h": [], "rep": false, "img": "s4-q144", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-145", "no": "145", "c": "k4", "src": "翰林 A卷 第9回 第 18 題", "st": "考卷", "pk": "ha-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 3, "ctx": "", "fig": "", "q": "有關光或聲音的傳播速率，下列敘述何者正確？", "o": ["兩者皆可在真空中傳播", "先看到閃電再聽到雷聲，可證明光速比聲速快", "光在玻璃的傳播速率大於在水中的傳播速率", "聲音在水中的傳播速率大於在玻璃中的傳播速率"], "a": 1, "e": "光可以在真空中傳播，聲音不行，(A) 錯。\n先看到閃電再聽到雷聲，證明光速比聲速快，(B) 正確。\n光速：水＞玻璃；聲速：玻璃（固體）＞水（液體），(C)(D) 都說反了。\n★ 光：介質愈密愈慢；聲音：固體＞液體＞氣體。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-146", "no": "146", "c": "k14", "src": "翰林 A卷 第9回 素養題 2", "st": "考卷", "pk": "ha-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 3, "ctx": "", "fig": "", "q": "以紅色、藍色兩張玻璃紙重疊看日光下各占 25% 面積的紅色、綠色、藍色、白色圖案時，看到各色所占面積百分比為下列何者？", "o": ["紅色 50%", "藍色 50%", "綠色 25%", "黑色 100%"], "a": 3, "e": "日光先穿過紅色玻璃紙只剩紅光，紅光再遇到藍色玻璃紙會被吸收，最後沒有光進入眼睛。\n所以不論原來是什麼顏色的圖案，看到的都是黑色，黑色 100%。\n★ 紅＋藍兩張玻璃紙重疊 → 什麼光都過不去。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-147", "no": "147", "c": "k11", "src": "翰林 A卷 第9回 素養題 3", "st": "考卷", "pk": "ha-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 3, "ctx": "", "fig": "", "q": "手拿一透鏡置於紙面上方 10 公分處，觀看紙面上的英文字母，結果如右圖所示，則有關此透鏡的敘述，下列何者正確？", "o": ["焦距小於 10 公分的凹透鏡", "焦距小於 10 公分的凸透鏡", "焦距大於 10 公分的凹透鏡", "焦距大於 10 公分的凸透鏡"], "a": 3, "e": "透過透鏡看到的字是正立而且放大 → 正立放大虛像，只有凸透鏡能做到。\n凸透鏡成正立放大虛像時，物體在焦點內：物距 10 公分＜焦距 → 焦距大於 10 公分。\n★ 正立放大 → 凸透鏡、物在焦點內。", "h": [], "rep": false, "img": "s4-q147", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-148", "no": "148", "c": "k9", "src": "翰林 A卷 第9回 素養題 4", "st": "考卷", "pk": "ha-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 3, "ctx": "", "fig": "", "q": "尚新將石子放入裝水的水桶中，從水面上方看到水中的石子時，下列何圖為合理的光線路徑與方向？", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 2, "e": "看到水中的石子，是石子反射的光從水中射出進入眼睛 → 光線方向由石子射向眼睛。\n光從水（慢）進入空氣（快）會偏離法線，空氣中的光線比水中的更斜。\n圖 (C) 符合這兩點。\n★ 先看箭頭方向，再看偏向或偏離法線。", "h": [], "rep": true, "img": "s4-q148", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-149", "no": "149", "c": "k12", "src": "翰林 A卷 第9回 素養題 5", "st": "考卷", "pk": "ha-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 3, "ctx": "", "fig": "", "q": "客凡去做視力檢測，發現其結果如下圖所示，則客凡應該要配戴下列哪一種鏡片矯正？", "o": ["放大鏡用的鏡片", "凸凹透鏡", "凹凸透鏡", "平凸透鏡"], "a": 1, "e": "圖中遠處的光線會聚在視網膜「前方」，遠處看不清楚 → 近視。\n近視要配戴使光發散的凹透鏡。選項中「凸凹透鏡」中央薄、邊緣厚，屬於凹透鏡。\n放大鏡、平凸透鏡、凹凸透鏡都是凸透鏡（中央厚、邊緣薄）。\n★ 凸凹透鏡＝凹透鏡；凹凸透鏡＝凸透鏡（看中央厚還是薄）。", "h": [], "rep": false, "img": "s4-q149", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-150", "no": "150", "c": "k5", "src": "翰林 A卷 第9回 活用題 6", "st": "考卷", "pk": "ha-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 3, "ctx": "", "fig": "兩相交成 60° 的平面鏡 AC 與 BO，光線入射 AO 夾角為 45°", "q": "右圖為光線反射的示意圖，AO、BO 兩平面鏡的鏡面夾角為 60°；有一光線射向 AO 鏡，且與 AO 鏡面的夾角為 45°，求光線自 BO 鏡面反射出時，反射角是多少？", "o": ["15°", "45°", "60°", "75°"], "a": 0, "e": "光線與 AO 鏡面夾角 45°，反射光與 AO 鏡面也成 45°。\n反射光、AO、BO 圍成三角形：與 BO 鏡面的夾角＝180°－60°－45°＝75°。\n在 BO 鏡的入射角＝90°－75°＝15°，反射角也是 15°。\n★ 先求光線和鏡面的夾角，最後再換成和法線的夾角。", "h": ["反射光與 AO 鏡面的夾角是多少？", "用三角形內角和求出光線與 BO 鏡面的夾角，再用 90° 減掉。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-151", "no": "151", "c": "k11", "src": "講義 p.155", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "以一張與放大鏡大小相同的黑紙，並剪了三個小圓圈如右圖，並黏貼在透鏡上，則在紙屏上的成像變化何者正確？", "o": ["變成三個正立的三角形", "變成三個倒立的三角形", "變成三個圓形", "一個亮度較暗的倒立三角形"], "a": 3, "e": "黑紙只是擋住大部分的光，透鏡上三個小圓孔仍有光通過。\n透鏡每一部分都能形成完整的像，所以紙屏上仍是一個完整的倒立三角形，只是光變少、亮度變暗。\n★ 遮住透鏡一部分：像完整、只變暗。", "h": [], "rep": false, "img": "s4-q151", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s4-152", "no": "152", "c": "k11", "src": "講義 p.155", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "某考古學家進行探勘時，發現岩壁上有許多很小的符號。若要使得符號看起來成放大的像，以便看得更清楚，則他應採取下列何種方法？", "o": ["透過凸透鏡觀看符號", "透過凹透鏡觀看符號", "藉著凸面鏡的反射觀看符號", "藉著平面鏡的反射觀看符號"], "a": 0, "e": "要看到放大的像，可以用凸透鏡當放大鏡：符號在焦點內 → 正立放大虛像。\n凹透鏡、凸面鏡只能成縮小的像，平面鏡成等大的像。\n★ 想放大看清楚 → 凸透鏡（放大鏡）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-153", "no": "153", "c": "k11", "src": "講義 p.155", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "小華從凸透鏡與凹透鏡中任意選擇一個透鏡，利用選擇的透鏡進行透鏡成像實驗，將蠟燭放在距離透鏡左側 6 cm 處，如右圖所示，他無論如何調整紙屏的位置，都無法清晰成像於紙屏上，改以眼睛由紙屏端經透鏡望向蠟燭，觀察到正立縮小的蠟燭像。若仍使用此透鏡，且將蠟燭移動至距離透鏡左側 13 cm 處，則此時所觀察到的蠟燭像其性質應屬於下列何者？", "o": ["正立縮小的像", "正立放大的像", "倒立縮小的像", "倒立放大的像"], "a": 0, "e": "蠟燭在 6 cm 處時無論如何都不能在紙屏上成像，從另一側看到「正立縮小」的像 → 這是凹透鏡（凸透鏡的虛像是放大的）。\n凹透鏡不管物體放在哪裡，都只成正立縮小虛像，所以移到 13 cm 處仍是正立縮小的像。\n★ 正立縮小虛像 → 凹透鏡；凹透鏡只有這一種像。", "h": [], "rep": false, "img": "s4-q153", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s4-154", "no": "154", "c": "k6", "src": "講義 p.163", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "靜香在 Q 點觀察，如右圖，若靜香想要見到光源 P 在平面鏡上所成的像，則進入靜香眼中的光線，必定是由光源 P 射向哪一區域的光線？", "o": ["AB", "BC", "CD", "DE"], "a": 1, "e": "先畫出光源 P 在平面鏡中的像 P'。靜香看到像，是因為反射光看起來從 P' 射向她的眼睛 Q。\n連接 P' 和 Q，連線和鏡面的交點落在 BC 之間，所以光是由 P 射向鏡面 BC 區域再反射進眼睛。\n★ 找反射點：連接「像點」和「眼睛」。", "h": [], "rep": false, "img": "s4-q154", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s4-155", "no": "155", "c": "k7", "src": "講義 p.163", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "如右圖，有關凹面鏡之敘述，下列何者錯誤？", "o": ["利用光的反射原理", "入射角必定等於反射角", "入射線 A 的反射線為 OG", "由 F 點發出光線經反射的光線必平行 FC"], "a": 2, "e": "凹面鏡利用光的反射，每一條光線都遵守反射定律，(A)(B) 正確。\n平行主軸的入射線 A，反射後會通過焦點 F，不是 OG，所以 (C) 錯誤。\n光路可逆：由焦點 F 發出的光，經凹面鏡反射後會平行主軸射出，(D) 正確。\n★ 凹面鏡：平行光 ↔ 焦點。", "h": [], "rep": false, "img": "s4-q155", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-156", "no": "156", "c": "k8", "src": "講義 p.164", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "如右圖所示，一個未裝水的容器置於水平桌面上，在其上方放置一個與容器底面平行的凹透鏡。今有兩道相距 3 cm 的平行雷射光，由凹透鏡上方鉛直射向容器，雷射光經過凹透鏡後偏折，照射在容器底部所形成的兩個光點距離為 10 cm。若在容器內注滿水，待水面平靜後，容器底部兩個光點的距離為 X cm，則下列何者正確？", "o": ["X > 10", "X = 10", "3 < X < 10", "X < 3"], "a": 2, "e": "沒裝水時，兩道光經凹透鏡發散，在底部相距 10 cm。\n注滿水後，光從空氣斜射入水中會偏向法線（變得比較直），所以光點之間的距離會變小。\n但光仍然是發散的，距離還是比原來的 3 cm 大，所以 3＜X＜10。\n★ 斜射入水中 → 偏向法線、變得比較陡。", "h": [], "rep": false, "img": "s4-q156", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s4-157", "no": "157", "c": "k11", "src": "講義 p.164", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "四個選項分別繪出凸透鏡與凹透鏡折射光束之幾何走向對照圖", "q": "下列各種光線折射的圖形，何者正確？", "o": ["光線穿過平行玻璃磚後，出射光線偏向下方，與入射光線不平行", "平行主軸的光線射入凹透鏡後，會聚於另一側的焦點 F", "平行主軸的光線射入凸透鏡後，向上偏折、遠離主軸", "通過凸透鏡焦點 F 的光線，經凸透鏡折射後平行主軸射出"], "a": 3, "e": "平行玻璃磚的出射光應該和入射光平行，(A) 錯。\n凹透鏡會讓平行主軸的光發散，不會會聚，(B) 錯。\n平行主軸的光經凸透鏡應該會聚，不會向上遠離主軸，(C) 錯。\n通過凸透鏡焦點的光，折射後會平行主軸射出，(D) 正確。\n★ 凸透鏡三條特殊光線：平行主軸→過焦點；過焦點→平行主軸；過光心→直線前進。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}], "extras": [{"id": "compare", "title": "易混淆比較", "html": "<h3>三大面鏡成像性質與應用比較表</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>平面鏡</th><th>凸面鏡（發散反射）</th><th>凹面鏡（會聚反射）</th></tr></thead><tbody><tr><td>鏡面幾何形狀</td><td>平整平面</td><td>反射面向外隆起</td><td>反射面向內凹陷</td></tr><tr><td>對光線的作用</td><td>僅改變方向，不聚不散</td><td>發散光線</td><td>會聚光線</td></tr><tr><td>成像性質</td><td>恆成正立等大虛像</td><td>恆成正立縮小虛像</td><td>物在焦點內成正立放大虛像；物在焦點外成倒立實像</td></tr><tr><td>物距與像距</td><td>物距等於像距（p = q）</td><td>像距恆小於焦距（鏡後）</td><td>隨物距位置劇烈改變</td></tr><tr><td>視野範圍</td><td>正常視野</td><td>視野最廣（縮小景物）</td><td>視野最小（局部放大）</td></tr><tr><td>生活典型應用</td><td>穿衣鏡、潛望鏡、室內梳妝鏡</td><td>道路轉彎反射鏡、車側後視鏡、商店防竊鏡</td><td>手電筒反射罩、車頭燈、太陽爐、牙醫額鏡</td></tr></tbody></table></div><h3>凸透鏡 vs. 凹透鏡特性比較表</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>凸透鏡（會聚透鏡）</th><th>凹透鏡（發散透鏡）</th></tr></thead><tbody><tr><td>外觀外形特徵</td><td>中央部分厚、邊緣較薄</td><td>中央部分薄、邊緣較厚</td></tr><tr><td>平行光照射反應</td><td>折射後向內會聚於鏡後焦點</td><td>折射後向外發散，反向延伸於鏡前焦點</td></tr><tr><td>焦點性質</td><td>實焦點（真實光線相交）</td><td>虛焦點（虛擬延長線相交）</td></tr><tr><td>可成影像種類</td><td>倒立縮小實像、倒立等大實像、倒立放大實像、正立放大虛像</td><td>只能形成正立、縮小虛像</td></tr><tr><td>近距離看字效果</td><td>看到正立放大的字體（放大鏡）</td><td>看到正立縮小的字體</td></tr><tr><td>視力矯正應用</td><td>矯正遠視眼與老花眼</td><td>矯正近視眼</td></tr></tbody></table></div><h3>實像 vs. 虛像核心辨析表</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>實像</th><th>虛像</th></tr></thead><tbody><tr><td>光線交會本質</td><td>由光線實際相交匯聚而成</td><td>由光線的反向延長線交會而成（非光線真正到達）</td></tr><tr><td>能否在紙屏成像</td><td>能在紙屏（屏幕）上顯現清晰影像</td><td>無法在紙屏上呈現（屏幕上只有光暈或無像）</td></tr><tr><td>肉眼能否直接看見</td><td>能直接看見（眼睛在光線前進路徑上）</td><td>能透過光學元件（鏡面、透鏡）直接看到</td></tr><tr><td>倒正方向規律</td><td>面鏡或透鏡成像中，實像必定為倒立</td><td>面鏡或透鏡成像中，虛像必定為正立</td></tr><tr><td>本章實例歸納</td><td>針孔成像、照相機底片上的像、投影機屏幕上的像</td><td>平面鏡中的像、凸面鏡中的像、放大鏡看到的像、水中虛像</td></tr></tbody></table></div><h3>眼睛 vs. 照相機構造與成像對照表</h3><div class=\"tbl\"><table><thead><tr><th>照相機構造</th><th>人眼眼球構造</th><th>具備之光學功能與成像特點</th></tr></thead><tbody><tr><td>鏡頭（凸透鏡組）</td><td>水晶體</td><td>折射光線並匯聚成像（人眼靠睫狀肌調節水晶體厚薄變焦）</td></tr><tr><td>光圈</td><td>瞳孔</td><td>調節進入鏡頭／眼球的光線多寡（亮處縮小、暗處放大）</td></tr><tr><td>快門</td><td>眼瞼（眼皮）</td><td>控制曝光時間的長短</td></tr><tr><td>感光元件／底片</td><td>視網膜</td><td>影像實際接收成像的界面，兩者皆形成「倒立縮小實像」</td></tr><tr><td>調焦方式</td><td>前後伸縮鏡頭（改變像距）</td><td>改變水晶體厚度與曲率（改變焦距）</td></tr></tbody></table></div><h3>近視眼 vs. 遠視眼與視力矯正比較表</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>近視眼（Myopia）</th><th>遠視眼（Hyperopia）</th></tr></thead><tbody><tr><td>視覺障礙特徵</td><td>看近處清楚，看遠處模糊</td><td>看遠處清楚，看近處模糊</td></tr><tr><td>生理成因</td><td>眼球前後徑過長，或水晶體太厚（折光力太強、焦距太短）</td><td>眼球前後徑過短，或水晶體太薄（折光力不足、焦距過長）</td></tr><tr><td>成像未矯正位置</td><td>遠處物體成像於視網膜之前</td><td>近處物體成像於視網膜之後</td></tr><tr><td>矯正所用鏡片</td><td>凹透鏡（發散透鏡）</td><td>凸透鏡（會聚透鏡）</td></tr><tr><td>矯正光學機制</td><td>先發散平行光線，使成像焦點向後延展至視網膜上</td><td>先匯聚散開光線，使成像焦點向前拉回至視網膜上</td></tr></tbody></table></div><h3>透明體 vs. 不透明體顏色判定表</h3><div class=\"tbl\"><table><thead><tr><th>物體類型</th><th>呈色機制</th><th>入射白光照射時</th><th>入射紅光照射時</th><th>入射綠光照射時</th></tr></thead><tbody><tr><td>紅色透明玻璃片</td><td>透過紅光，吸收其他色光</td><td>呈紅色（紅光穿透）</td><td>呈紅色（紅光穿透）</td><td>呈黑色（綠光被吸收無光透過）</td></tr><tr><td>紅色不透明紙卡</td><td>反射紅光，吸收其他色光</td><td>呈紅色（反射白光中的紅光）</td><td>呈紅色（反射入射紅光）</td><td>呈黑色（綠光被吸收無光反射）</td></tr><tr><td>白色不透明紙卡</td><td>反射所有色光</td><td>呈白色（反射紅綠藍白光）</td><td>呈紅色（反射入射紅光）</td><td>呈綠色（反射入射綠光）</td></tr><tr><td>黑色不透明紙卡</td><td>吸收所有色光</td><td>呈黑色（吸收所有光）</td><td>呈黑色（吸收紅光）</td><td>呈黑色（吸收綠光）</td></tr></tbody></table></div>"}, {"id": "timeline", "title": "流程與計算步驟", "html": "<h3>凸透鏡三條特殊光線成像作圖流程</h3><div class=\"tbl\"><table><thead><tr><th>步驟階段</th><th>作圖操作指引</th><th>光學物理依據與重點說明</th></tr></thead><tbody><tr><td>步驟一：第一條特殊光線</td><td>由物體頂端發出平行於主軸的光線，射向透鏡中心線</td><td>經透鏡折射後，折射光線必定通過鏡後另一側的焦點（F）。</td></tr><tr><td>步驟二：第二條特殊光線</td><td>由物體頂端發出射向透鏡<b>鏡心（O）</b>的光線</td><td>通過薄透鏡中心的入射光線，前進方向維持直線不變。</td></tr><tr><td>步驟三：第三條特殊光線</td><td>由物體頂端發出射向<b>鏡前同側焦點（F）</b>的光線</td><td>經透鏡折射後，折射光線必定平行於主軸射出。</td></tr><tr><td>步驟四：像的位置判定</td><td>取上述任兩條折射光線的交會點（或反向延長線交會點）</td><td>1. 折射光線實際相交 → 為倒立實像； 2. 折射光線發散，其反向延長線相交 → 為正立虛像。</td></tr></tbody></table></div><h3>凹透鏡特殊光線作圖流程</h3><div class=\"tbl\"><table><thead><tr><th>步驟階段</th><th>作圖操作指引</th><th>光學物理依據與重點說明</th></tr></thead><tbody><tr><td>步驟一：第一條特殊光線</td><td>由物體頂端發出平行於主軸的光線，射向透鏡中心線</td><td>經凹透鏡折射後向外發散，其反向虛擬延長線必定通過同側鏡前焦點（F）。</td></tr><tr><td>步驟二：第二條特殊光線</td><td>由物體頂端直接射向<b>鏡心（O）</b>的光線</td><td>通過鏡心的光線完全不偏折，維持直線前進。</td></tr><tr><td>步驟三：虛像位置判定</td><td>標出第一條光線的反向延長線與第二條直線光線的交點</td><td>兩線交會於鏡前焦距內，垂直主軸作圖即得正立、縮小虛像。</td></tr></tbody></table></div><h3>光線在三稜鏡色散與彩虹形成歷程</h3><div class=\"tbl\"><table><thead><tr><th>階段序號</th><th>物理歷程階段</th><th>光學機制與特徵變化說明</th></tr></thead><tbody><tr><td>階段一：首次折射入滴</td><td>太陽白光由空氣斜射進入水滴或三稜鏡</td><td>光速驟減發生偏折，各色光因速率不同產生角度分離，紅光偏折最小、紫光偏折最大。</td></tr><tr><td>階段二：滴內單次反射</td><td>色光傳播至水滴後表面界面</td><td>大部分光線在水滴內壁產生單次內部全反射，光線折轉方向。</td></tr><tr><td>階段三：再次折射出滴</td><td>反射光線由水滴內部射出進入空氣</td><td>光速增加再次偏折，各色光的角度差進一步擴大射向觀察者。</td></tr><tr><td>階段四：眼球感知色帶</td><td>觀察者背向太陽仰望天空</td><td>上方水滴射入紅光、下方水滴射入紫光，眼球視網膜接收到上紅下紫的圓弧彩虹。</td></tr></tbody></table></div>"}, {"id": "charts", "title": "圖表判讀", "html": "<h3>針孔成像幾何關係圖</h3><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">• 清楚看懂光源（如蠟燭火焰）、針孔、紙屏（半透明描圖紙）的三點一直線幾何對應。</p><p class=\"li sub\">• 藉由頂點穿過針孔至紙屏底端、底點穿過針孔至紙屏頂端的交叉線，理解為何成像是「<b>上下顛倒、左右相反</b>」。</p><p class=\"li\"><b>常見判讀方式</b>：</p><p class=\"li sub\">• <b>像的大小計算</b>：利用相似三角形高與底邊成正比：fractext{像長}}{text物長 =frac{text像距text{物距}}</p><p class=\"li sub\">• 若將光源順時針旋轉，紙屏上的像亦為順時針旋轉（倒轉 180^° 判定）。</p><h3>平面鏡對稱作圖與視野判定圖</h3><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">• 物體與像關於鏡面完全對稱，物距等於像距（p=q），物像連線垂直鏡面。</p><p class=\"li sub\">• 人眼能從鏡中看見某物體的「鏡中視角範圍」（由眼睛連接鏡子兩端點，再向外延伸所夾之梯形光錐區域）。</p><p class=\"li\"><b>常見判讀方式</b>：</p><p class=\"li sub\">• <b>找像位置</b>：將物體對鏡面作垂線並等長延伸至鏡後，標出像點 P' 39, 41；</p><p class=\"li sub\">• <b>視線光路圖</b>：由眼睛位置 E 連線至鏡後像點 P'，此連線與鏡面的交點即為光線射在鏡面的反射點，依此補齊反射入射光線。</p><h3>光的折射偏折幾何圖（快慢介質折射圖）</h3><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">• 入射線、法線（垂直界面線）與折射線的幾何方位。</p><p class=\"li sub\">• 當光由「快介質（空氣）」斜射入「慢介質（水或玻璃）」時，折射光向法線靠攏，angle r < angle i；</p><p class=\"li sub\">• 當光由「慢介質」斜射入「快介質」時，折射光遠離法線，angle r > angle i。</p><p class=\"li\"><b>常見判讀方式</b>：</p><p class=\"li sub\">• 只要比對「光線與法線的夾角」，<b>夾角大的那一側必定光速較快</b>，夾角小的那一側必定光速較慢，據此可直接逆推各介質光速大小（如 v 空氣 > v 水 > v 玻璃）。</p><h3>凸透鏡六大位置成像規律走勢圖</h3><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">• 橫軸標記主軸基準點：鏡心 O、焦點 F、兩倍焦點 2F。</p><p class=\"li sub\">• 物體由無窮遠處逐漸移近透鏡時，實像從另一側焦點 F 逐漸向外推移至 2F 外，且像由縮小漸變為放大。</p><p class=\"li\"><b>常見判讀方式</b>：</p><p class=\"li sub\">• <b>物距與像距消長法則（物進像退）</b>：在焦點外，物體向透鏡靠近（物距變小），實像必定遠離透鏡（像距變大），且像長愈變愈大。</p><p class=\"li sub\">• <b>2f 處為分水嶺</b>：p = 2f 時像距恰等於 2f，此時物像等大；物距小於 2f 則成放大實像；物距大於 2f 則成縮小實像。</p><h3>三稜鏡色散與彩虹光譜圖</h3><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">• 白光斜向射入三稜鏡後，在玻璃第一界面與第二界面發生兩次折射，色光散開。</p><p class=\"li sub\">• 了解光譜排列順序由頂至底為紅、橙、黃、綠、藍、靛、紫。</p><p class=\"li\"><b>常見判讀方式</b>：</p><p class=\"li sub\">• <b>偏折角判讀</b>：沿原入射白光延長線比對，最靠近原本前進方向的是紅光（偏折最少），偏折最劇烈的是紫光（偏向底邊最多）。</p>"}, {"id": "tips", "title": "口訣與防錯", "html": "<h3>理化關鍵必背口訣</h3><p class=\"li\"><b>折射快慢偏角口訣</b>：</p><div class=\"poem\"><b>「快入慢，偏向法；慢入快，偏離法；速度快，角度大！」</b>（光速快的介質中，光線與法線夾角必定較大；光速慢的介質中，夾角必定較小。）</div><p class=\"li\"><b>透鏡成像虛實與正倒口訣</b>：</p><div class=\"poem\"><b>「實像必倒立，虛像必正立；一倍焦距分虛實，兩倍焦距分大小！」</b>（物在 f 外必成倒立實像，物在 f 內必成正立放大虛像；凸透鏡 2f 外成像縮小，2f 內成像放大。）</div><p class=\"li\"><b>凸透鏡成像動態走勢口訣</b>：</p><div class=\"poem\"><b>「物進像退像變大，物退像進像變小；焦點之內放大虛，愈近鏡面像愈小。」</b></div><p class=\"li\"><b>平面鏡成像特徵口訣</b>：</p><div class=\"poem\"><b>「物像對稱垂直切，等大正立虛像成；鏡長只需身高半，退後前進像不變。」</b></div><p class=\"li\"><b>三原色混合口訣</b>：</p><div class=\"poem\"><b>「紅加綠為黃，綠加藍為青，紅加藍為洋紅，三原聚白光。」</b></div><p class=\"li\"><b>物體顏色判定口訣</b>：</p><div class=\"poem\"><b>「透明看透過，不透明看反射；同色照顯原本色，異色照來一片黑（白紙隨人變，黑體全不見）。」</b></div>"}]});
